function isValidTimeZone(value: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value }).format(new Date());
    return true;
  } catch {
    return false;
  }
}

function normalizeTimeZone(value: string | null | undefined): string {
  const normalized = (value || "").trim();
  if (!normalized) {
    return DEFAULT_USER_TIME_ZONE;
  }
  return isValidTimeZone(normalized) ? normalized : DEFAULT_USER_TIME_ZONE;
}

function listSupportedTimeZones(): string[] {
  const intlWithSupportedValues = Intl as unknown as {
    supportedValuesOf?: (key: string) => string[];
  };

  const raw = intlWithSupportedValues.supportedValuesOf?.("timeZone") ?? [];
  if (Array.isArray(raw) && raw.length > 0) {
    const deduped = Array.from(new Set(raw.map((item) => item.trim()).filter((item) => item.length > 0)));
    if (!deduped.includes(DEFAULT_USER_TIME_ZONE)) {
      deduped.unshift(DEFAULT_USER_TIME_ZONE);
    }
    return deduped.sort((left, right) => left.localeCompare(right));
  }

  return [DEFAULT_USER_TIME_ZONE, "UTC"];
}

function formatDate(
  value: string | null | undefined,
  timeZone: string = DEFAULT_USER_TIME_ZONE,
): string {
  if (!value) {
    return "Não definido";
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "Não definido";
  }

  return parsed.toLocaleString("pt-BR", {
    timeZone: normalizeTimeZone(timeZone),
  });
}

function formatDateOnly(
  value: string | null | undefined,
  timeZone: string = DEFAULT_USER_TIME_ZONE,
): string {
  if (!value) {
    return "Não definido";
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "Não definido";
  }

  return parsed.toLocaleDateString("pt-BR", {
    timeZone: normalizeTimeZone(timeZone),
  });
}

function formatRelativeTime(
  value: string | null | undefined,
  timeZone: string = DEFAULT_USER_TIME_ZONE,
): string {
  if (!value) {
    return "agora";
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return formatDate(value, timeZone);
  }

  const diffMs = Date.now() - parsed.getTime();
  if (!Number.isFinite(diffMs) || diffMs < 0) {
    return formatDate(value, timeZone);
  }

  const minuteMs = 60 * 1000;
  const hourMs = 60 * minuteMs;
  const dayMs = 24 * hourMs;

  if (diffMs < minuteMs) {
    return "agora";
  }

  if (diffMs < hourMs) {
    const minutes = Math.max(1, Math.floor(diffMs / minuteMs));
    return `há ${minutes} min`;
  }

  if (diffMs < dayMs) {
    const hours = Math.max(1, Math.floor(diffMs / hourMs));
    return `há ${hours} h`;
  }

  const days = Math.max(1, Math.floor(diffMs / dayMs));
  return `há ${days} ${days === 1 ? "dia" : "dias"}`;
}

type AvisoTone = "auth" | "error" | "info" | "success" | "neutral" | "whatsapp";

function isWhatsappAviso(aviso: Pick<Aviso, "kind" | "title" | "message">): boolean {
  const normalizedKind = aviso.kind.trim().toUpperCase();
  const normalizedTitle = aviso.title.trim().toUpperCase();
  const normalizedMessage = aviso.message.trim().toUpperCase();

  if (normalizedKind === "JOB_WHATSAPP_RELINK_CREATED") {
    return true;
  }

  if (normalizedTitle === "RELINK NO WHATSAPP") {
    return true;
  }

  return normalizedMessage.startsWith("WHATSAPP STATUS");
}

function isAuthAviso(aviso: Pick<Aviso, "kind" | "title" | "message">): boolean {
  const normalizedKind = aviso.kind.trim().toUpperCase();
  const normalizedTitle = aviso.title.trim().toUpperCase();
  const normalizedMessage = aviso.message.trim().toUpperCase();

  if (normalizedKind === "JOB_WAITING_LOGIN" || normalizedKind === "JOB_RATE_LIMIT") {
    return true;
  }

  if (
    normalizedTitle.includes("RENOVAÇÃO") ||
    normalizedTitle.includes("RENOVACAO") ||
    normalizedTitle.includes("LOGIN")
  ) {
    return true;
  }

  return (
    normalizedMessage.includes("PRECISA DE RENOVAÇÃO") ||
    normalizedMessage.includes("PRECISA DE RENOVACAO") ||
    normalizedMessage.includes("EXPIR") ||
    normalizedMessage.includes("LOGIN")
  );
}

function isApprovalPositiveAviso(aviso: Pick<Aviso, "kind" | "title" | "message">): boolean {
  const normalizedKind = aviso.kind.trim().toUpperCase();
  const normalizedTitle = aviso.title.trim().toUpperCase();

  if (normalizedKind === "APPROVAL_DECISION") {
    return normalizedTitle.includes("PROJETO APROVADO") || normalizedTitle.includes("APROVADO");
  }

  return false;
}

function isApprovalNegativeAviso(aviso: Pick<Aviso, "kind" | "title" | "message">): boolean {
  const normalizedKind = aviso.kind.trim().toUpperCase();
  const normalizedTitle = aviso.title.trim().toUpperCase();

  if (normalizedKind === "APPROVAL_DECISION") {
    return (
      normalizedTitle.includes("PROJETO NÃO APROVADO") ||
      normalizedTitle.includes("PROJETO NAO APROVADO") ||
      normalizedTitle.includes("PROJETO REJEITADO") ||
      normalizedTitle.includes("NÃO APROVADO") ||
      normalizedTitle.includes("NAO APROVADO") ||
      normalizedTitle.includes("REJEITADO")
    );
  }

  return false;
}

function avisoTone(aviso: Pick<Aviso, "kind" | "title" | "message">): AvisoTone {
  if (isWhatsappAviso(aviso)) {
    return "whatsapp";
  }

  if (isApprovalNegativeAviso(aviso)) {
    return "error";
  }

  if (isApprovalPositiveAviso(aviso)) {
    return "success";
  }

  const normalizedKind = aviso.kind.trim().toUpperCase();
  if (normalizedKind === "FEEDBACK") {
    return "info";
  }
  if (isAuthAviso(aviso)) {
    return "auth";
  }
  if (normalizedKind === "JOB_FAILED") {
    return "error";
  }
  if (normalizedKind === "SYSTEM_BROADCAST") {
    return "success";
  }
  if (normalizedKind === "JOB_SENT" || normalizedKind === "JOB_SENT_UNCONFIRMED") {
    return "info";
  }
  return "neutral";
}

function avisoToneClass(aviso: Pick<Aviso, "kind" | "title" | "message">): string {
  return `notice-tone-${avisoTone(aviso)}`;
}

function resolveNoticeIconByKey(iconKey: string | null | undefined): IconType | null {
  const normalized = typeof iconKey === "string" ? iconKey.trim() : "";
  if (!normalized) {
    return null;
  }

  const option = NOTICE_ICON_OPTIONS.find((entry) => entry.key === normalized);
  return option?.icon ?? null;
}

function resolveAvisoPopoverIcon(aviso: Pick<Aviso, "kind" | "title" | "message" | "iconKey">): IconType {
  const customIcon = resolveNoticeIconByKey(aviso.iconKey);
  if (customIcon) {
    return customIcon;
  }
  if (isApprovalNegativeAviso(aviso)) {
    return FiSlash;
  }
  if (isApprovalPositiveAviso(aviso)) {
    return FiThumbsUp;
  }
  const normalizedKind = aviso.kind.trim().toUpperCase();
  if (normalizedKind === "FEEDBACK") {
    return FiMessageCircle;
  }
  const tone = avisoTone(aviso);
  if (tone === "success") {
    return FiCheckCircle;
  }
  if (tone === "error" || tone === "auth") {
    return FiAlertCircle;
  }
  if (tone === "whatsapp") {
    return FaWhatsapp;
  }
  return FiBell;
}

function resolveAvisoPopoverThumbClass(aviso: Pick<Aviso, "kind" | "title" | "message">): string {
  if (isApprovalNegativeAviso(aviso)) {
    return "notices-entry-thumb-approval-negative";
  }
  if (isApprovalPositiveAviso(aviso)) {
    return "notices-entry-thumb-approval-positive";
  }
  return `notices-entry-thumb-${avisoTone(aviso)}`;
}

function resolveJobDisplayTitle(job: Pick<Job, "id" | "title" | "caption">): string {
  const normalizedTitle = job.title?.trim();
  if (normalizedTitle) {
    return normalizedTitle;
  }

  const normalizedCaption = job.caption?.trim();
  if (normalizedCaption) {
    return normalizedCaption;
  }

  return `Job ${job.id}`;
}

type PublicationPreviewCommentTreeNode = PublicationPreviewComment & {
  replies: PublicationPreviewCommentTreeNode[];
};

function buildPublicationPreviewCommentTree(
  comments: PublicationPreviewComment[],
): PublicationPreviewCommentTreeNode[] {
  const byId = new Map<string, PublicationPreviewCommentTreeNode>();
  const roots: PublicationPreviewCommentTreeNode[] = [];

  comments.forEach((comment) => {
    byId.set(comment.id, {
      ...comment,
      replies: [],
    });
  });

  comments.forEach((comment) => {
    const node = byId.get(comment.id);
    if (!node) {
      return;
    }

    if (comment.parentCommentId) {
      const parentNode = byId.get(comment.parentCommentId);
      if (parentNode) {
        parentNode.replies.push(node);
        return;
      }
    }

    roots.push(node);
  });

  return roots;
}

function resolveHistoryCalendarTitle(job: Pick<Job, "id" | "title">): string {
  const normalizedTitle = job.title?.trim();
  if (normalizedTitle) {
    return normalizedTitle;
  }

  return "Sem título";
}

function clampCompactPublicationTitle(title: string, maxChars = 24): string {
  const normalizedTitle = title.trim();
  if (normalizedTitle.length <= maxChars) {
    return normalizedTitle;
  }

  return `${normalizedTitle.slice(0, Math.max(0, maxChars - 1)).trimEnd()}…`;
}

function clampNumber(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function buildCalendarDayKey(year: number, month: number, day: number): string {
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function isCalendarDayInPast(dayKey: string, referenceDayKey: string): boolean {
  return dayKey < referenceDayKey;
}

function shiftCalendarMonth(year: number, month: number, delta: number): { year: number; month: number } {
  const absoluteMonth = year * 12 + (month - 1) + delta;
  const nextYear = Math.floor(absoluteMonth / 12);
  const nextMonth = (absoluteMonth % 12 + 12) % 12;
  return {
    year: nextYear,
    month: nextMonth + 1,
  };
}

function getDaysInMonth(year: number, month: number): number {
  return new Date(Date.UTC(year, month, 0, 12, 0, 0)).getUTCDate();
}

function getCalendarWeekdayIndex(year: number, month: number, day: number): number {
  const weekday = new Date(Date.UTC(year, month - 1, day, 12, 0, 0)).getUTCDay();
  return (weekday + 6) % 7;
}

function formatHistoryCalendarMonthLabel(year: number, month: number): string {
  return new Intl.DateTimeFormat("pt-BR", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, month - 1, 1, 12, 0, 0)));
}

function formatHistoryCalendarTimeZoneLabel(timeZone: string): string {
  return timeZone.replace(/_/g, " ");
}

function loadImageForCanvas(sourceUrl: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.decoding = "async";
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Não foi possível carregar a imagem para edição do story."));
    image.src = sourceUrl;
  });
}

function formatJobScheduledAt(job: Pick<Job, "publicationState" | "dataPostagem">, timeZone: string): string {
  if (!job.dataPostagem || Number.isNaN(new Date(job.dataPostagem).getTime())) {
    return "Data e hora indefinida";
  }
  return formatDate(job.dataPostagem, timeZone);
}

function toDateLocal(value: string, timeZone: string): string {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "";
  }

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: normalizeTimeZone(timeZone),
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(parsed);

  const mapped: Record<string, string> = {};
  for (const part of parts) {
    if (part.type !== "literal") {
      mapped[part.type] = part.value;
    }
  }

  return `${mapped.year ?? "0000"}-${mapped.month ?? "01"}-${mapped.day ?? "01"}`;
}

function toTimeLocal(value: string, timeZone: string): string {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "";
  }

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: normalizeTimeZone(timeZone),
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(parsed);

  const mapped: Record<string, string> = {};
  for (const part of parts) {
    if (part.type !== "literal") {
      mapped[part.type] = part.value;
    }
  }

  return `${mapped.hour ?? "00"}:${mapped.minute ?? "00"}`;
}

function toIsoFromTimeZoneDateTime(
  dateValue: string,
  timeValue: string,
  timeZone: string,
): string | null {
  const [yearRaw, monthRaw, dayRaw] = dateValue.split("-").map((part) => Number.parseInt(part, 10));
  const [hourRaw, minuteRaw] = timeValue.split(":").map((part) => Number.parseInt(part, 10));

  if (
    !Number.isFinite(yearRaw) ||
    !Number.isFinite(monthRaw) ||
    !Number.isFinite(dayRaw) ||
    !Number.isFinite(hourRaw) ||
    !Number.isFinite(minuteRaw)
  ) {
    return null;
  }

  const year = yearRaw;
  const month = monthRaw;
  const day = dayRaw;
  const hour = hourRaw;
  const minute = minuteRaw;
  const normalizedTimeZone = normalizeTimeZone(timeZone);
  const targetComparableMs = Date.UTC(year, month - 1, day, hour, minute, 0);
  let utcMs = targetComparableMs;

  for (let attempt = 0; attempt < 3; attempt += 1) {
    const parts = new Intl.DateTimeFormat("en-GB", {
      timeZone: normalizedTimeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
    }).formatToParts(new Date(utcMs));

    const mapped: Record<string, string> = {};
    for (const part of parts) {
      if (part.type !== "literal") {
        mapped[part.type] = part.value;
      }
    }

    const observedComparableMs = Date.UTC(
      Number.parseInt(mapped.year ?? "0", 10),
      Number.parseInt(mapped.month ?? "1", 10) - 1,
      Number.parseInt(mapped.day ?? "1", 10),
      Number.parseInt(mapped.hour ?? "0", 10),
      Number.parseInt(mapped.minute ?? "0", 10),
      0,
    );

    const deltaMs = observedComparableMs - targetComparableMs;
    if (deltaMs === 0) {
      break;
    }

    utcMs -= deltaMs;
  }

  const result = new Date(utcMs);
  if (Number.isNaN(result.getTime())) {
    return null;
  }

  return result.toISOString();
}

function buildScheduledPayload(
  dateValue: string,
  timeValue: string,
  timeZone: string,
): {
  dataPostagem: string;
  scheduledDateLocal: string;
  scheduledTimeLocal: string;
  timeZone: string;
} | null {
  const iso = toIsoFromTimeZoneDateTime(dateValue, timeValue, timeZone);
  if (!iso) {
    return null;
  }

  return {
    dataPostagem: iso,
    scheduledDateLocal: dateValue,
    scheduledTimeLocal: timeValue,
    timeZone: normalizeTimeZone(timeZone),
  };
}

function parseInstagramOauthWindowMessage(data: unknown): InstagramOauthWindowMessage | null {
  if (!data || typeof data !== "object") {
    return null;
  }

  const payload = data as Record<string, unknown>;
  if (payload.type !== "socialup-instagram-oauth" || typeof payload.success !== "boolean") {
    return null;
  }

  return {
    type: "socialup-instagram-oauth",
    success: payload.success,
    message: typeof payload.message === "string" ? payload.message : undefined,
    connectionId: typeof payload.connectionId === "string" ? payload.connectionId : null,
  };
}

function parseGoogleOauthWindowMessage(data: unknown): GoogleOauthWindowMessage | null {
  if (!data || typeof data !== "object") {
    return null;
  }

  const payload = data as Record<string, unknown>;
  if (payload.type !== "socialup-google-oauth" || typeof payload.success !== "boolean") {
    return null;
  }

  return {
    type: "socialup-google-oauth",
    success: payload.success,
    message: typeof payload.message === "string" ? payload.message : undefined,
    sessionToken: typeof payload.sessionToken === "string" ? payload.sessionToken : null,
    user: payload.user && typeof payload.user === "object" ? (payload.user as AuthUser) : null,
  };
}

function parsePostForMeOauthWindowMessage(data: unknown): PostForMeOauthWindowMessage | null {
  if (!data || typeof data !== "object") {
    return null;
  }

  const payload = data as Record<string, unknown>;
  if (payload.type !== "socialup-postforme-oauth") {
    return null;
  }

  const connectionId =
    typeof payload.connectionId === "string" && payload.connectionId.trim()
      ? payload.connectionId.trim()
      : null;

  return {
    type: "socialup-postforme-oauth",
    connectionId,
    success: typeof payload.success === "boolean" ? payload.success : undefined,
    message: typeof payload.message === "string" ? payload.message : undefined,
    accountId: typeof payload.accountId === "string" ? payload.accountId : null,
  };
}

function parsePostForMeOauthPreviewWindowMessage(data: unknown): PostForMeOauthPreviewWindowMessage | null {
  if (!data || typeof data !== "object") {
    return null;
  }

  const payload = data as Record<string, unknown>;
  if (payload.type !== "socialup-postforme-oauth-preview-success") {
    return null;
  }

  const connectionId =
    typeof payload.connectionId === "string" && payload.connectionId.trim()
      ? payload.connectionId.trim()
      : null;

  return {
    type: "socialup-postforme-oauth-preview-success",
    connectionId,
    accountId: typeof payload.accountId === "string" ? payload.accountId : null,
  };
}

function isPostForMeOauthCloseWindowMessage(data: unknown): data is PostForMeOauthCloseWindowMessage {
  if (!data || typeof data !== "object") {
    return false;
  }

  const payload = data as Record<string, unknown>;
  return payload.type === "socialup-postforme-oauth-close";
}

function isPopupWindowContext(): boolean {
  if (typeof window === "undefined") {
    return false;
  }

  try {
    return Boolean(window.opener && !window.opener.closed);
  } catch {
    return false;
  }
}

function requestPopupWindowClose(): void {
  if (typeof window === "undefined") {
    return;
  }

  try {
    window.close();
  } catch {
    // ignore
  }

  try {
    window.open("about:blank", "_self");
    window.close();
  } catch {
    // ignore
  }

  try {
    window.location.replace("about:blank");
  } catch {
    // ignore
  }

  window.setTimeout(() => {
    try {
      window.close();
    } catch {
      // ignore
    }
  }, 30);
}

function closeManagedPopupWindow(popupWindow: Window | null | undefined): void {
  if (!popupWindow || popupWindow.closed) {
    return;
  }

  try {
    popupWindow.close();
  } catch {
    // ignore
  }

  try {
    popupWindow.focus();
    popupWindow.close();
  } catch {
    // ignore
  }

  try {
    popupWindow.open("about:blank", "_self");
    popupWindow.close();
  } catch {
    // ignore
  }

  try {
    popupWindow.location.href = "about:blank";
    popupWindow.close();
  } catch {
    // ignore
  }
}

function clearManagedPopupWatch(intervalRef: MutableRefObject<number | null>): void {
  if (intervalRef.current !== null && typeof window !== "undefined") {
    window.clearInterval(intervalRef.current);
    intervalRef.current = null;
  }
}

function readPostForMePopupResult():
  | {
      provider: string;
      success: boolean;
      accountId: string | null;
      connectionId: string | null;
      message: string | null;
    }
  | null {
  if (typeof window === "undefined") {
    return null;
  }

  const params = new URLSearchParams(window.location.search);
  const provider = (params.get("provider") || "").trim().toLowerCase();
  const isSuccess = (params.get("isSuccess") || "").trim().toLowerCase();
  const accountId = (params.get("accountId") || "").trim() || null;
  const connectionId = (params.get(POST_FOR_ME_CONNECTION_ID_QUERY_PARAM) || "").trim() || null;
  const projectId = (params.get("projectId") || "").trim();
  const message =
    (params.get("message") || params.get("error_description") || params.get("errorMessage") || params.get("error") || "")
      .trim() || null;

  if (!provider || (!projectId && !accountId && !isSuccess)) {
    return null;
  }

  return {
    provider,
    success: isSuccess !== "false" && isSuccess !== "0",
    accountId,
    connectionId,
    message,
  };
}

function resolvePostForMePopupFailureMessage(message: string | null | undefined): string {
  const normalized = message?.trim() || "";
  return normalized || "Falha ao concluir a conexão da conta.";
}

function openCenteredPopup(name: string, width: number, height: number): Window | null {
  if (typeof window === "undefined") {
    return null;
  }

  const dualScreenLeft = window.screenLeft ?? 0;
  const dualScreenTop = window.screenTop ?? 0;
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || screen.width;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || screen.height;
  const left = Math.max(0, Math.round(dualScreenLeft + (viewportWidth - width) / 2));
  const top = Math.max(0, Math.round(dualScreenTop + (viewportHeight - height) / 2));

  const popup = window.open(
    "",
    name,
    [
      "popup=yes",
      "toolbar=no",
      "location=no",
      "status=no",
      "menubar=no",
      "scrollbars=yes",
      "resizable=yes",
      `width=${width}`,
      `height=${height}`,
      `left=${left}`,
      `top=${top}`,
    ].join(","),
  );

  if (!popup) {
    return null;
  }

  try {
    popup.document.write(`<!doctype html>
<html lang="pt-BR">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Conectando conta</title>
    <style>
      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        background: #f7f8fb;
        color: #273142;
        font: 16px/1.4 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }
      .shell {
        display: grid;
        gap: 14px;
        justify-items: center;
        text-align: center;
        padding: 24px;
      }
      .spinner {
        width: 28px;
        height: 28px;
        border-radius: 999px;
        border: 3px solid rgba(217, 16, 122, 0.18);
        border-top-color: #d9107a;
        animation: spin 0.8s linear infinite;
      }
      .label {
        font-size: 15px;
        font-weight: 500;
      }
      .hint {
        color: #6f7b91;
        font-size: 13px;
      }
      @keyframes spin {
        to { transform: rotate(360deg); }
      }
    </style>
  </head>
  <body>
    <div class="shell">
      <div class="spinner" aria-hidden="true"></div>
      <div class="label">Preparando conexao da conta...</div>
      <div class="hint">Esta janela vai continuar automaticamente.</div>
    </div>
  </body>
</html>`);
    popup.document.close();
  } catch {
    // Alguns navegadores podem restringir a escrita inicial da janela.
  }

  return popup;
}

