function drawRoundedRect(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
) {
  const safeRadius = clamp(radius, 0, Math.min(width, height) / 2);
  context.beginPath();
  context.moveTo(x + safeRadius, y);
  context.lineTo(x + width - safeRadius, y);
  context.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
  context.lineTo(x + width, y + height - safeRadius);
  context.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
  context.lineTo(x + safeRadius, y + height);
  context.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
  context.lineTo(x, y + safeRadius);
  context.quadraticCurveTo(x, y, x + safeRadius, y);
  context.closePath();
}

function storyStrokeSvgPath(points: StoryEditorStrokePoint[]): string {
  if (points.length === 0) {
    return "";
  }

  const [firstPoint, ...rest] = points;
  if (!firstPoint) {
    return "";
  }

  if (rest.length === 0) {
    return `M ${Math.round(firstPoint.x * 1000)} ${Math.round(firstPoint.y * 1000)}`;
  }

  let path = `M ${Math.round(firstPoint.x * 1000)} ${Math.round(firstPoint.y * 1000)}`;
  const allPoints = [firstPoint, ...rest];
  for (let index = 1; index < allPoints.length - 1; index += 1) {
    const currentPoint = allPoints[index];
    const nextPoint = allPoints[index + 1];
    if (!currentPoint || !nextPoint) {
      continue;
    }
    const midX = (currentPoint.x + nextPoint.x) / 2;
    const midY = (currentPoint.y + nextPoint.y) / 2;
    path += ` Q ${Math.round(currentPoint.x * 1000)} ${Math.round(currentPoint.y * 1000)} ${Math.round(midX * 1000)} ${Math.round(midY * 1000)}`;
  }
  const lastPoint = allPoints[allPoints.length - 1];
  if (lastPoint) {
    path += ` L ${Math.round(lastPoint.x * 1000)} ${Math.round(lastPoint.y * 1000)}`;
  }
  return path;
}

function drawStrokeOnCanvas(
  context: CanvasRenderingContext2D,
  points: StoryEditorStrokePoint[],
  canvasWidth: number,
  canvasHeight: number,
) {
  if (points.length <= 1) {
    return;
  }

  const firstPoint = points[0];
  if (!firstPoint) {
    return;
  }

  context.beginPath();
  context.moveTo(firstPoint.x * canvasWidth, firstPoint.y * canvasHeight);

  for (let index = 1; index < points.length - 1; index += 1) {
    const currentPoint = points[index];
    const nextPoint = points[index + 1];
    if (!currentPoint || !nextPoint) {
      continue;
    }
    const midX = (currentPoint.x + nextPoint.x) / 2;
    const midY = (currentPoint.y + nextPoint.y) / 2;
    context.quadraticCurveTo(
      currentPoint.x * canvasWidth,
      currentPoint.y * canvasHeight,
      midX * canvasWidth,
      midY * canvasHeight,
    );
  }

  const lastPoint = points[points.length - 1];
  if (lastPoint) {
    context.lineTo(lastPoint.x * canvasWidth, lastPoint.y * canvasHeight);
  }

  context.stroke();
}

function requiresInstagramImageSizeLimit(
  publicationType: SchedulerPublicationType,
  fileName: string,
): boolean {
  const isImage = isInstagramPostImagePath(fileName);
  return publicationType === "instagram_post" || (publicationType === "instagram_story" && isImage);
}

function schedulerMediaValidationMessage(
  publicationType: SchedulerPublicationType,
  fileName: string,
  fileSizeBytes?: number | null,
): string | null {
  if (publicationType === "instagram_post" && !isInstagramPostImagePath(fileName)) {
    return "Instagram Post aceita apenas imagens JPG ou PNG.";
  }

  if (publicationType === "instagram_reel" && !isInstagramReelVideoPath(fileName)) {
    return "Instagram Reel aceita apenas vídeo MP4.";
  }

  if (publicationType === "instagram_story" && !/\.(jpg|jpeg|png|mp4|mov|m4v|webm)$/i.test(fileName)) {
    return "Stories aceita imagem (JPG/PNG) ou vídeo (MP4/MOV/M4V/WEBM).";
  }

  if (publicationType === "tiktok_post" && !/\.(mp4|mov|m4v|webm)$/i.test(fileName)) {
    return "TikTok aceita apenas vídeo.";
  }

  if (
    typeof fileSizeBytes === "number" &&
    fileSizeBytes > INSTAGRAM_IMAGE_MAX_SIZE_BYTES &&
    requiresInstagramImageSizeLimit(publicationType, fileName)
  ) {
    return `Imagem acima do limite para Instagram (${formatMegabytes(INSTAGRAM_IMAGE_MAX_SIZE_BYTES)} MB). ` +
      `Arquivo atual: ${formatMegabytes(fileSizeBytes)} MB.`;
  }

  return null;
}

function schedulerSelectionMaxFiles(publicationType: SchedulerPublicationType): number {
  if (publicationType === "threads_post") {
    return THREADS_MULTI_MEDIA_MAX_FILES;
  }

  if (publicationType === "x_post") {
    return X_MULTI_MEDIA_MAX_FILES;
  }
  if (publicationType === "facebook_post") {
    return INSTAGRAM_MULTI_MEDIA_MAX_FILES;
  }
  if (publicationType === "instagram_post" || publicationType === "instagram_story") {
    return INSTAGRAM_MULTI_MEDIA_MAX_FILES;
  }

  return 1;
}

function schedulerMultiMediaMaxFiles(publicationType: SchedulerPublicationType): number {
  return schedulerSelectionMaxFiles(publicationType);
}

function isSchedulerVideoPrimaryPublicationType(publicationType: SchedulerPublicationType): boolean {
  return (
    publicationType === "instagram_reel" ||
    publicationType === "tiktok_post"
  );
}

function supportsSchedulerWhatsappRelink(publicationType: SchedulerPublicationType): boolean {
  return (
    publicationType === "instagram_post" ||
    publicationType === "instagram_reel" ||
    publicationType === "instagram_story" ||
    publicationType === "threads_post" ||
    publicationType === "x_post" ||
    publicationType === "tiktok_post"
  );
}

function isStoriesStatusOnlySchedulerSelection(
  selection: SchedulerPublicationType[],
): boolean {
  return (
    selection.length === 2 &&
    selection.includes("instagram_story") &&
    selection.includes("whatsapp_status_midia")
  );
}

function supportsStoriesStatusFlexibleMediaSelection(
  selection: SchedulerPublicationType[],
): boolean {
  return (
    selection.includes("instagram_story") &&
    selection.includes("whatsapp_status_midia") &&
    !selection.includes("instagram_reel") &&
    !selection.includes("tiktok_post")
  );
}

function validateFacebookSchedulerMediaSelection(fileNames: string[]): string | null {
  const normalizedFileNames = fileNames
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);

  if (normalizedFileNames.length === 0) {
    return null;
  }

  const videoCount = normalizedFileNames.filter((entry) => isSchedulerVideoMediaFileName(entry)).length;
  if (videoCount === 0) {
    return null;
  }

  if (videoCount === 1 && normalizedFileNames.length === 1) {
    return null;
  }

  return "Facebook aceita múltiplas imagens no feed ou apenas 1 vídeo por vez.";
}

function schedulerWhatsappRelinkValidationMessage(
  publicationType: SchedulerPublicationType,
  mediaCount: number,
): string | null {
  if (!supportsSchedulerWhatsappRelink(publicationType)) {
    return null;
  }

  if (publicationType === "instagram_story" && mediaCount > 1) {
    return "Relink no WhatsApp para story funciona apenas com 1 mídia por vez.";
  }

  if ((publicationType === "threads_post" || publicationType === "x_post") && mediaCount === 0) {
    return `Relink no WhatsApp para ${publicationType === "threads_post" ? "Threads" : "X"} exige ao menos 1 mídia publicada.`;
  }

  if (publicationType === "tiktok_post" && mediaCount === 0) {
    return "Relink no WhatsApp para TikTok exige 1 vídeo publicado.";
  }

  return null;
}

function readImageAspectRatioFromFile(file: File): Promise<number> {
  return new Promise((resolve, reject) => {
    const objectUrl = URL.createObjectURL(file);
    const image = new Image();

    image.onload = () => {
      try {
        const width = image.naturalWidth || 0;
        const height = image.naturalHeight || 0;
        if (width <= 0 || height <= 0) {
          reject(new Error("Dimensões da imagem inválidas."));
          return;
        }
        resolve(width / height);
      } finally {
        URL.revokeObjectURL(objectUrl);
      }
    };

    image.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      reject(new Error("Falha ao ler imagem."));
    };

    image.src = objectUrl;
  });
}

async function schedulerMediaAdvancedValidationMessage(
  publicationType: SchedulerPublicationType,
  file: File,
): Promise<string | null> {
  if (publicationType !== "instagram_post" || !isInstagramPostImagePath(file.name)) {
    return null;
  }

  try {
    const aspectRatio = await readImageAspectRatioFromFile(file);
    if (aspectRatio < INSTAGRAM_POST_ASPECT_RATIO_MIN || aspectRatio > INSTAGRAM_POST_ASPECT_RATIO_MAX) {
      return (
        `Proporção da imagem não suportada para Instagram Post. ` +
        `Use entre 4:5 (${formatAspectRatio(INSTAGRAM_POST_ASPECT_RATIO_MIN)}:1) e 1.91:1. ` +
        `Atual: ${formatAspectRatio(aspectRatio)}:1.`
      );
    }
  } catch {
    return "Não foi possível validar a proporção da imagem. Use JPG/PNG sem corrupção.";
  }

  return null;
}

