function workspaceInitials(name: string): string {
  const chunks = name
    .split(/\s+/)
    .map((chunk) => chunk.trim())
    .filter(Boolean)
    .slice(0, 2);

  if (chunks.length === 0) {
    return "WS";
  }

  return chunks
    .map((chunk) => chunk.charAt(0).toUpperCase())
    .join("")
    .slice(0, 2);
}

function userInitials(name: string | null | undefined, username?: string | null): string {
  const base = name?.trim() || username?.trim() || "User";
  const chunks = base
    .replace(/^@+/, "")
    .split(/\s+/)
    .map((chunk) => chunk.trim())
    .filter(Boolean)
    .slice(0, 2);

  if (chunks.length === 0) {
    return "SU";
  }

  return chunks
    .map((chunk) => chunk.charAt(0).toUpperCase())
    .join("")
    .slice(0, 2);
}

function hexToRgba(hex: string, alpha: number): string {
  const normalized = hex.replace("#", "").trim();
  if (!/^[0-9a-fA-F]{6}$/.test(normalized)) {
    return `rgba(31, 42, 68, ${alpha})`;
  }

  const red = Number.parseInt(normalized.slice(0, 2), 16);
  const green = Number.parseInt(normalized.slice(2, 4), 16);
  const blue = Number.parseInt(normalized.slice(4, 6), 16);
  return `rgba(${red}, ${green}, ${blue}, ${alpha})`;
}

function availableWorkspaceInviteRoles(company: Company): Array<"CLIENT" | "AGENCY"> {
  if (company.kind === "AGENCY_BONUS") {
    return ["AGENCY"];
  }

  const hasPendingClientInvite = company.invites.some((invite) => invite.role === "CLIENT" && !invite.usedAt && !invite.revokedAt);
  if (company.hasClientMember || hasPendingClientInvite) {
    return ["AGENCY"];
  }

  return ["CLIENT", "AGENCY"];
}

