function shouldShowConnectionSyncAction(
  connection: SocialConnection,
  options?: { forceExpired?: boolean },
): boolean {
  if (connection.provider !== "POST_FOR_ME") {
    return false;
  }

  if (!connection.providerAccountId?.trim()) {
    return false;
  }

  const normalizedProviderStatus = (connection.providerStatus || "").trim().toLowerCase();
  if (normalizedProviderStatus === "awaiting_remote_connection" || normalizedProviderStatus === "auth_in_progress") {
    return false;
  }

  return Boolean(options?.forceExpired) || isConnectionManualRenewalExpired(connection);
}

function resolveWhatsappOwnerNumber(ownerJid: string | null | undefined): string | null {
  const raw = ownerJid?.trim() || "";
  if (!raw) {
    return null;
  }

  const base = raw.split("@")[0]?.trim() || "";
  if (!base) {
    return null;
  }

  const digits = base.replace(/\D+/g, "");
  return digits || base;
}

function isSchedulerEligibleConnection(
  connection: SocialConnection,
  platform: SocialConnection["platform"],
): boolean {
  if (connection.platform !== platform) {
    return false;
  }

  if (connection.authStatus === "CONNECTED") {
    return true;
  }

  return platform === "instagram" && connection.hasSecret && Boolean(connection.loginIdentifier);
}

function resolveSchedulerTargetAccountLabel(connection: SocialConnection): string {
  if (connection.platform === "instagram") {
    const fallbackInstagramUsername =
      connection.loginIdentifier && !/^\d+$/.test(connection.loginIdentifier) ? connection.loginIdentifier : null;
    const instagramUsername = connection.instagramUsername?.trim() || fallbackInstagramUsername;
    if (instagramUsername) {
      return instagramUsername.startsWith("@") ? instagramUsername : `@${instagramUsername}`;
    }
    return connection.displayName;
  }

  if (connection.platform === "threads") {
    const threadsUsername = connection.threadsUsername?.trim() || connection.loginIdentifier?.trim() || "";
    if (threadsUsername) {
      return threadsUsername.startsWith("@") ? threadsUsername : `@${threadsUsername}`;
    }
    return connection.displayName;
  }

  if (connection.platform === "tiktok" || connection.platform === "x") {
    const username = connection.loginIdentifier?.trim() || "";
    if (username) {
      return username.startsWith("@") ? username : `@${username}`;
    }
    return connection.displayName;
  }

  if (connection.platform === "facebook") {
    return connection.loginIdentifier?.trim() || connection.displayName;
  }

  return connection.whatsappProfileName?.trim() || resolveWhatsappOwnerNumber(connection.whatsappOwnerJid) || connection.displayName;
}

function resolveSchedulerTargetAccountMeta(connection: SocialConnection): string | null {
  if (connection.platform === "instagram") {
    return connection.displayName;
  }

  if (connection.platform === "threads") {
    return connection.displayName;
  }

  if (connection.platform === "facebook") {
    return null;
  }

  if (connection.platform === "tiktok" || connection.platform === "x") {
    return connection.displayName;
  }

  const ownerNumber = resolveWhatsappOwnerNumber(connection.whatsappOwnerJid);
  const profileName = connection.whatsappProfileName?.trim() || null;
  const displayName = connection.displayName?.trim() || null;
  const accountLabel = resolveSchedulerTargetAccountLabel(connection).trim();

  if (ownerNumber && ownerNumber !== accountLabel) {
    return ownerNumber.replace(/^@/, "");
  }

  if (ownerNumber && profileName && profileName !== ownerNumber && profileName !== accountLabel) {
    return profileName;
  }

  if (displayName && displayName !== ownerNumber && displayName !== accountLabel) {
    return displayName;
  }

  if (!displayName && ownerNumber && ownerNumber !== accountLabel) {
    return profileName;
  }

  return null;
}

function normalizeConnectionDispatchDedupToken(value: string | null | undefined): string {
  return (value || "").trim().toLowerCase().replace(/^@+/, "");
}

function resolveConnectionDispatchDedupKey(connection: SocialConnection): string {
  const normalizedPlatform = connection.platform.trim().toLowerCase();

  if (connection.platform === "whatsapp") {
    const ownerNumber = resolveWhatsappOwnerNumber(connection.whatsappOwnerJid);
    if (ownerNumber) {
      return `${normalizedPlatform}:owner:${ownerNumber}`;
    }

    const normalizedProfileName = normalizeConnectionDispatchDedupToken(connection.whatsappProfileName);
    if (normalizedProfileName) {
      return `${normalizedPlatform}:profile:${normalizedProfileName}`;
    }

    return `${normalizedPlatform}:connection:${connection.id}`;
  }

  const providerAccountId = connection.providerAccountId?.trim() || "";
  if (providerAccountId) {
    return `${normalizedPlatform}:provider:${providerAccountId}`;
  }

  const providerExternalId = normalizeConnectionDispatchDedupToken(connection.providerExternalId);
  if (providerExternalId) {
    return `${normalizedPlatform}:external:${providerExternalId}`;
  }

  if (connection.platform === "instagram") {
    const instagramUserId = normalizeConnectionDispatchDedupToken(connection.instagramUserId);
    if (instagramUserId) {
      return `${normalizedPlatform}:user:${instagramUserId}`;
    }

    const instagramUsername = normalizeConnectionDispatchDedupToken(connection.instagramUsername || connection.loginIdentifier);
    if (instagramUsername) {
      return `${normalizedPlatform}:login:${instagramUsername}`;
    }
  }

  if (connection.platform === "threads") {
    const threadsUserId = normalizeConnectionDispatchDedupToken(connection.threadsUserId);
    if (threadsUserId) {
      return `${normalizedPlatform}:user:${threadsUserId}`;
    }

    const threadsUsername = normalizeConnectionDispatchDedupToken(connection.threadsUsername || connection.loginIdentifier);
    if (threadsUsername) {
      return `${normalizedPlatform}:login:${threadsUsername}`;
    }
  }

  const loginIdentifier = normalizeConnectionDispatchDedupToken(connection.loginIdentifier);
  if (loginIdentifier) {
    return `${normalizedPlatform}:login:${loginIdentifier}`;
  }

  return `${normalizedPlatform}:connection:${connection.id}`;
}

function dedupeConnectionIdsByDispatchKey(
  connectionIds: string[],
  availableConnections: SocialConnection[],
): string[] {
  const connectionById = new Map(availableConnections.map((connection) => [connection.id, connection] as const));
  const seenDispatchKeys = new Set<string>();
  const uniqueIds: string[] = [];

  for (const connectionId of connectionIds) {
    const connection = connectionById.get(connectionId);
    if (!connection) {
      continue;
    }

    const dispatchKey = resolveConnectionDispatchDedupKey(connection);
    if (seenDispatchKeys.has(dispatchKey)) {
      continue;
    }

    seenDispatchKeys.add(dispatchKey);
    uniqueIds.push(connectionId);
  }

  return uniqueIds;
}

function isInstagramPublication(publicationType: SchedulerPublicationType): boolean {
  return (
    publicationType === "instagram_post" ||
    publicationType === "instagram_reel" ||
    publicationType === "instagram_story"
  );
}

function supportsMetaLocationPublication(publicationType: SchedulerPublicationType): boolean {
  void publicationType;
  // Temporarily disabled in the scheduler until we have a reliable source of valid Meta location page IDs.
  return false;
}

function normalizeSchedulerHashtagValue(value: string): string | null {
  const normalized = value
    .trim()
    .replace(/^#+/, "")
    .replace(/\s+/g, "")
    .replace(/[^\p{L}\p{N}_]/gu, "")
    .toLowerCase();

  if (!normalized) {
    return null;
  }

  return normalized.slice(0, 64);
}

function parseStorySequenceFailureMeta(lastError: string | null | undefined): {
  publishedCount: number;
  total: number;
} | null {
  const raw = (lastError || "").trim();
  if (!raw) {
    return null;
  }

  const match = raw.match(/STORY_SEQUENCE_PUBLISHED_COUNT=(\d+);STEP=(\d+);TOTAL=(\d+)/i);
  if (!match || !match[1] || !match[3]) {
    return null;
  }

  const publishedCount = Number.parseInt(match[1], 10);
  const total = Number.parseInt(match[3], 10);
  if (!Number.isFinite(publishedCount) || !Number.isFinite(total)) {
    return null;
  }

  return {
    publishedCount: Math.max(0, publishedCount),
    total: Math.max(1, total),
  };
}

