    try {
      await api.delete(`/companies/${companyId}/invites/${inviteId}`);
      setCompanyInfo("Convite revogado com sucesso.");
      await loadAll();
    } catch (inviteError) {
      setError(inviteError instanceof Error ? inviteError.message : "Falha ao revogar convite.");
    }
