  async function retryGroupedJobs(jobsToRetry: Job[], anchorJobId: string) {
    if (jobsToRetry.length === 0) {
      return;
    }

    setError("");
    setRetryingJobId(anchorJobId);
    setHistoryInfo(
      jobsToRetry.length > 1
        ? `Reenfileirando ${jobsToRetry.length} redes falhadas...`
        : "Reenfileirando postagem...",
    );

    try {
      for (const job of jobsToRetry) {
        await api.postJson(`/jobs/${job.id}/retry`, {});
      }
      setHistoryInfo(
        jobsToRetry.length > 1
          ? `${jobsToRetry.length} redes falhadas foram reenfileiradas para tentativa imediata.`
          : "Postagem reenfileirada para tentativa imediata.",
      );
      await loadAll();
      window.scrollTo({ top: 0, behavior: "smooth" });
    } catch (retryError) {
      setHistoryInfo("");
      setError(retryError instanceof Error ? retryError.message : "Falha ao reenfileirar a postagem.");
    } finally {
      setRetryingJobId(null);
    }
  }

  async function rescheduleFailedMedia(job: Job) {
    const partialMeta = parseStorySequenceFailureMeta(job.lastError);
    const isPartialStoryFailure =
      job.publicationType === "instagram_story" &&
      partialMeta !== null &&
      partialMeta.publishedCount > 0 &&
      partialMeta.publishedCount < partialMeta.total;

    setError("");
    setReschedulingFailedMediaJobId(job.id);
    setHistoryInfo(
      isPartialStoryFailure
        ? "Reagendando apenas as mídias restantes para daqui a 20 minutos..."
        : "Reagendando a mídia para daqui a 20 minutos...",
    );

    try {
      const result = await api.postJson<{
        scheduledAt: string;
        mediaCount: number;
        totalCount: number;
        remainingOnly: boolean;
      }>(`/jobs/${job.id}/reschedule-failed-media`, {});

      setHistoryInfo(
        result.remainingOnly
          ? `${result.mediaCount} mídia(s) restante(s) reagendadas para daqui a 20 minutos.`
          : `${result.mediaCount} mídia(s) reagendadas para daqui a 20 minutos.`,
      );
      await loadAll();
      window.scrollTo({ top: 0, behavior: "smooth" });
    } catch (rescheduleError) {
      setHistoryInfo("");
      setError(rescheduleError instanceof Error ? rescheduleError.message : "Falha ao reagendar a mídia.");
    } finally {
      setReschedulingFailedMediaJobId(null);
    }
  }

  async function login(event: FormEvent) {
    event.preventDefault();
    if (Date.now() < suppressLoginSubmitUntilRef.current) {
      return;
    }
    setAuthError("");
    setAuthSubmitting(true);

    try {
      const result = await api.postJson<{ sessionToken: string; user: AuthUser }>("/auth/login", {
        identifier: loginIdentifier,
        password: loginPassword,
      });

      api.setSessionToken(result.sessionToken, rememberMe);
      if (rememberMe) {
        window.localStorage.setItem(REMEMBERED_USERNAME_STORAGE_KEY, loginIdentifier);
      } else {
        window.localStorage.removeItem(REMEMBERED_USERNAME_STORAGE_KEY);
      }
      setAuthUser(result.user);
      setLoginPassword("");
      setAuthInfo("");
      if (result.user.needsPlanSelection) {
        enterInitialPlanSelectionFlow(result.user);
        return;
      }
      if (readPendingPostForMeConnectionSync()) {
        setAuthInfo("Login concluído. Voltando para Conectar contas para finalizar a sincronização.");
        navigateToView("agents");
      } else {
        api.setPopupSessionHandoffToken("");
        navigateToView("dashboard");
      }
    } catch (loginError) {
      setAuthError(loginError instanceof Error ? loginError.message : "Falha ao fazer login.");
    } finally {
      setAuthSubmitting(false);
    }
  }

  function returnToLoginFromPasswordReset() {
    suppressLoginSubmitUntilRef.current = Date.now() + 1200;
    setAuthMode("login");
    setAuthError("");
    setAuthInfo("");
  }

  async function requestPasswordReset(event: FormEvent) {
    event.preventDefault();
    setAuthError("");
    setAuthInfo("");
    setRequestingPasswordReset(true);

    try {
      await api.postJson<{ ok: true }>("/auth/password-reset/request", {
        email: passwordResetEmail,
      });
      setAuthInfo("Se esse email estiver cadastrado, enviamos um link para redefinir a senha.");
    } catch (resetError) {
      setAuthError(resetError instanceof Error ? resetError.message : "Falha ao solicitar recuperação de senha.");
    } finally {
      setRequestingPasswordReset(false);
    }
  }

  async function confirmPasswordReset(event: FormEvent) {
    event.preventDefault();
    setAuthError("");
    setAuthInfo("");

    if (passwordResetPassword !== passwordResetConfirmPassword) {
      setAuthError("As senhas não conferem.");
      return;
    }

    setConfirmingPasswordReset(true);

    try {
      const result = await api.postJson<{ sessionToken: string; user: AuthUser }>("/auth/password-reset/confirm", {
        key: passwordResetKey,
        password: passwordResetPassword,
      });

      api.setSessionToken(result.sessionToken, true);
      window.localStorage.setItem(REMEMBERED_USERNAME_STORAGE_KEY, result.user.email || result.user.username);
      setPasswordResetKey("");
      setPasswordResetPassword("");
      setPasswordResetConfirmPassword("");
      setLoginIdentifier(result.user.email || result.user.username);
      setLoginPassword("");
      setAuthChecked(true);
      setAuthUser(result.user);
      setAuthMode("login");
      setAuthError("");
      setAuthInfo("");

      if (typeof window !== "undefined") {
        window.history.replaceState({}, "", VIEW_ROUTE_MAP.dashboard);
      }

      if (result.user.needsPlanSelection) {
        enterInitialPlanSelectionFlow(result.user);
        return;
      }

      navigateToView("dashboard");
    } catch (resetError) {
      setAuthError(resetError instanceof Error ? resetError.message : "Falha ao redefinir senha.");
    } finally {
      setConfirmingPasswordReset(false);
    }
  }

  function enterInitialPlanSelectionFlow(user: AuthUser) {
    if (typeof window !== "undefined") {
      const nextHref = buildViewHref("planStart");
      const nextUrl = new URL(nextHref, window.location.origin);
      const currentUrl = new URL(window.location.href);
      const currentComparable = `${normalizePath(currentUrl.pathname)}${currentUrl.search}`;
      const nextComparable = `${normalizePath(nextUrl.pathname)}${nextUrl.search}`;
      if (currentComparable !== nextComparable) {
        window.history.replaceState({}, "", `${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`);
      }
    }

    setAuthChecked(true);
    setAuthUser(user);
    setActiveView("planStart");
    setProfilePageTab("plan");
    setAuthError("");
    setAuthInfo("");
    setError("");
    setPlanInfo("");
    setBillingLoading(true);
    void loadBillingData({ withSkeleton: true });
  }

  async function startGoogleLogin() {
    setAuthError("");
    setAuthInfo("");
    setGoogleAuthScreenLocked(true);
    setGoogleAuthHandoffPending(false);
    googleAuthResultReceivedRef.current = false;
    setGoogleAuthSubmitting(true);

    try {
      const { idToken } = await signInWithGoogleViaFirebase();
      setGoogleAuthHandoffPending(true);
      const result = await api.postJson<{ sessionToken: string; user: AuthUser }>("/auth/firebase/google", {
        idToken,
      });

      api.setSessionToken(result.sessionToken, rememberMe);
      if (rememberMe) {
        const rememberedIdentifier = result.user.email?.trim() || result.user.username;
        window.localStorage.setItem(REMEMBERED_USERNAME_STORAGE_KEY, rememberedIdentifier);
      } else {
        window.localStorage.removeItem(REMEMBERED_USERNAME_STORAGE_KEY);
      }

      setAuthChecked(true);
      setLoginIdentifier(result.user.email || result.user.username);
      setLoginPassword("");
      setProfileName(result.user.name);
      setProfileEmail(result.user.email || "");
      setProfileUsername(result.user.username);
      setProfileTimeZone(result.user.timeZone || DEFAULT_USER_TIME_ZONE);
      setAuthError("");
      setAuthInfo("");

      if (result.user.needsPlanSelection) {
        enterInitialPlanSelectionFlow(result.user);
        return;
      }

      setAuthUser(result.user);

      if (readPendingPostForMeConnectionSync()) {
        setAuthInfo("Login concluído. Voltando para Conectar contas para finalizar a sincronização.");
        navigateToView("agents");
      } else {
        api.setPopupSessionHandoffToken("");
        navigateToView("dashboard");
      }
    } catch (googleError) {
      setGoogleAuthScreenLocked(false);
      setGoogleAuthHandoffPending(false);
      if (isFirebaseGoogleLoginCancelledError(googleError)) {
        setAuthError("");
      } else {
        setAuthError(resolveFirebaseGoogleLoginErrorMessage(googleError));
      }
      setAuthInfo("");
    } finally {
      setGoogleAuthSubmitting(false);
    }
  }

  async function logout() {
    try {
      await api.postJson<void>("/auth/logout", {});
    } catch {
      // ignore logout cleanup errors
    } finally {
      clearManagedPopupWatch(googleAuthPopupWatchIntervalRef);
      closeManagedPopupWindow(googleAuthPopupRef.current);
      googleAuthPopupRef.current = null;
      googleAuthResultReceivedRef.current = false;
      setGoogleAuthSubmitting(false);
      setGoogleAuthHandoffPending(false);
      setGoogleAuthScreenLocked(false);
      api.setSessionToken("");
      setAuthUser(null);
      setAuthChecked(true);
      setError("");
      setAuthInfo("");
      setAuthError("");
      setProfileTimeZone(DEFAULT_USER_TIME_ZONE);
      setProfileEmail("");
      setSetupEmail("");
      setNoticesPopoverOpen(false);
      setProfileMenuOpen(false);
      setSelectedCompanyId("");
      setActiveView("dashboard");
      contentLoadingCounterRef.current = 0;
      setContentLoading(false);
      if (typeof window !== "undefined") {
        window.history.replaceState({}, "", "/");
      }
    }
  }

  async function deleteAccount() {
    if (isRootUser) {
      setAuthError("A conta root não pode ser excluída.");
      return;
    }

    const challengeWords = ["socialup", "excluir", "confirmar", "workspace", "seguranca"];
    const challenge = challengeWords[Math.floor(Math.random() * challengeWords.length)] ?? "excluir";
    const typed = window.prompt(
      `Para excluir sua conta definitivamente, digite exatamente: ${challenge}`,
    );

    if (typed === null) {
      return;
    }

    if (typed.trim() !== challenge) {
      window.alert("Confirmação incorreta. A conta não foi excluída.");
      return;
    }

    setDeletingAccount(true);
    setError("");
    setAuthError("");

    try {
      await api.delete("/auth/account");
      api.setSessionToken("");
      setAuthUser(null);
      setAuthChecked(true);
      setNoticesPopoverOpen(false);
      setProfileMenuOpen(false);
      setSelectedCompanyId("");
      setActiveView("dashboard");
      contentLoadingCounterRef.current = 0;
      setContentLoading(false);
      window.history.replaceState({}, "", "/");
    } catch (deleteError) {
      setError(deleteError instanceof Error ? deleteError.message : "Falha ao excluir conta.");
    } finally {
      setDeletingAccount(false);
    }
  }

  async function createPublicUser(event: FormEvent) {
    event.preventDefault();
    setCreatingSignupUser(true);
    setAuthError("");
    setAuthInfo("");

    try {
      const fullName = [setupName.trim(), setupLastName.trim()].filter(Boolean).join(" ");
      const result = await api.postJson<{ sessionToken: string; user: AuthUser }>("/auth/register", {
        name: fullName,
        email: setupEmail,
        password: setupPassword,
      });

      api.setSessionToken(result.sessionToken, rememberMe);
      if (rememberMe) {
        window.localStorage.setItem(REMEMBERED_USERNAME_STORAGE_KEY, result.user.email || result.user.username);
      } else {
        window.localStorage.removeItem(REMEMBERED_USERNAME_STORAGE_KEY);
      }

      setSetupName("");
      setSetupLastName("");
      setSetupPassword("");
      setSetupUsername("");
      setLoginIdentifier(result.user.email || result.user.username);
      setLoginPassword("");
      setAuthError("");
      setAuthInfo("");

      if (result.user.needsPlanSelection) {
        enterInitialPlanSelectionFlow(result.user);
        return;
      }

      setAuthChecked(true);
      setAuthUser(result.user);
      navigateToView("dashboard");
    } catch (signupError) {
      setAuthError(signupError instanceof Error ? signupError.message : "Falha ao cadastrar usuario.");
    } finally {
      setCreatingSignupUser(false);
    }
  }

  async function createUserFromWorkspaceInvite(event: FormEvent) {
    event.preventDefault();
    if (!workspaceInviteKey) {
      setAuthError("Convite de workspace inválido.");
      return;
    }

    setCreatingWorkspaceInviteUser(true);
    setAuthError("");

    try {
      const result = await api.postJson<{ sessionToken: string; user: AuthUser }>("/auth/workspace-access/setup", {
        key: workspaceInviteKey,
        name: setupName,
        email: setupEmail,
        username: setupUsername,
        password: setupPassword,
      });

      api.setSessionToken(result.sessionToken, true);
      setAuthUser(result.user);
      setWorkspaceInvitePreview(null);
      setWorkspaceInviteKey("");
      setSetupName("");
      setSetupEmail("");
      setSetupUsername("");
      setSetupPassword("");
      setCompanyInfo("Workspace adicionado com sucesso.");
      const url = new URL(window.location.href);
      url.searchParams.delete("workspaceInviteKey");
      window.history.replaceState({}, "", url.toString());
      await loadAll();
      navigateToView("companies");
    } catch (inviteSetupError) {
      setAuthError(inviteSetupError instanceof Error ? inviteSetupError.message : "Falha ao criar usuário pelo convite.");
    } finally {
      setCreatingWorkspaceInviteUser(false);
    }
  }

  async function saveProfile(event: FormEvent) {
    event.preventDefault();
    setError("");

    try {
      const result = await api.putJson<{ user: AuthUser }>("/auth/profile", {
        name: profileName,
        email: profileEmail,
        username: profileUsername,
        password: profilePassword,
        timeZone: profileTimeZone,
      });

      setAuthUser(result.user);
      setProfileRouteUsername(normalizeProfileRouteUsername(result.user.username));
      setProfilePassword("");
      setAuthInfo("Perfil salvo com sucesso.");
    } catch (profileError) {
      setError(profileError instanceof Error ? profileError.message : "Falha ao salvar perfil.");
    }
  }

