  function renderNoticesBell(shellRef: { current: HTMLDivElement | null }, extraClassName = "") {
    const visibleUnreadNoticesCount =
      recentAvisosUnreadCounts.panel +
      recentAvisosUnreadCounts.socialup +
      (shouldShowFeedbackNotifications ? recentAvisosUnreadCounts.feedbacks : 0);
    const hasUnreadNotices = visibleUnreadNoticesCount > 0;
    const canMarkAllNoticesAsRead =
      hasUnreadNotices;
    const effectiveNoticesPopoverTab =
      noticesPopoverTab === "feedbacks" && !shouldShowFeedbackNotifications ? "panel" : noticesPopoverTab;
    const tabs: Array<{ key: NoticesPopoverTabKey; label: string; unreadCount: number; icon: IconType }> = [
      { key: "panel", label: "Painel", unreadCount: recentAvisosUnreadCounts.panel, icon: FiHome },
      ...(shouldShowFeedbackNotifications
        ? [{ key: "feedbacks" as const, label: "Feedbacks", unreadCount: recentAvisosUnreadCounts.feedbacks, icon: FiMessageCircle }]
        : []),
      {
        key: "socialup",
        label: "SocialUp",
        unreadCount: recentAvisosUnreadCounts.socialup,
        icon: FiMessageSquare,
      },
    ];

    function renderUpdatesTab(): ReactNode {
      if (noticesPopoverLoading) {
        return <div className="notices-popover-empty">Carregando notificações...</div>;
      }

      if (recentPanelAvisos.length === 0) {
        return (
          <div className="notices-popover-empty">
            <strong>Nada novo no painel</strong>
            <span>Quando surgir alguma atualização importante, ela aparece aqui.</span>
          </div>
        );
      }

      return recentPanelAvisos.map((aviso) => {
        const Icon = resolveAvisoPopoverIcon(aviso);
        const unread = !aviso.readAt;
        return (
          <article key={aviso.id} className="notices-entry-card">
            <span className={`notices-entry-thumb ${resolveAvisoPopoverThumbClass(aviso)}`} aria-hidden="true">
              <Icon />
            </span>
            <div className="notices-entry-copy">
              <div className="notices-entry-heading">
                <strong>{aviso.title}</strong>
                <span className="notices-entry-time">{formatRelativeTime(aviso.createdAt, effectiveUserTimeZone)}</span>
              </div>
              <p>{aviso.message}</p>
            </div>
            <div className="notices-entry-side">
              {renderNoticeReadState({
                unread,
                busy: markingAvisoReadId === aviso.id,
                onMarkRead: () => void markAvisoAsRead(aviso.id),
                unreadLabel: "Marcar notificação como lida",
                readLabel: "Notificação lida",
              })}
              <button
                type="button"
                className="notices-entry-delete"
                aria-label="Excluir notificação"
                title="Excluir notificação"
                onClick={() => void deleteAvisoFromPopover(aviso.id)}
                disabled={deletingAvisoId === aviso.id}
              >
                <FiTrash2 aria-hidden="true" />
              </button>
            </div>
          </article>
        );
      });
    }

    function renderFeedbackTab(): ReactNode {
      if (recentFeedbackAvisos.length === 0) {
        return (
          <div className="notices-popover-empty">
            <strong>Sem feedbacks no momento</strong>
            <span>Comentários de aprovação e reprovação vão aparecer separados aqui.</span>
          </div>
        );
      }

      return recentFeedbackAvisos.map((notice) => {
        const unread = !notice.readAt;
        const displayName = notice.createdBy?.name?.trim() || "Cliente";
        const username = notice.createdBy?.username?.trim() || "feedback";
        return (
          <article key={notice.id} className="notices-entry-card">
            <span className="notices-entry-avatar" aria-hidden="true">
              {userInitials(displayName, username)}
            </span>
            <div className="notices-entry-copy">
              <div className="notices-entry-heading">
                <strong>{displayName}</strong>
                <span className="notices-entry-time">{formatRelativeTime(notice.createdAt, effectiveUserTimeZone)}</span>
              </div>
              <span className="notices-entry-kicker">{notice.title}</span>
              <p>{notice.message}</p>
            </div>
            <div className="notices-entry-side">
              {renderNoticeReadState({
                unread,
                busy: markingAvisoReadId === notice.id,
                onMarkRead: () => void markAvisoAsRead(notice.id),
                unreadLabel: "Marcar feedback como lido",
                readLabel: "Feedback lido",
              })}
              <button
                type="button"
                className="notices-entry-delete"
                aria-label="Excluir feedback"
                title="Excluir feedback"
                onClick={() => void deleteAvisoFromPopover(notice.id)}
                disabled={deletingAvisoId === notice.id}
              >
                <FiTrash2 aria-hidden="true" />
              </button>
            </div>
          </article>
        );
      });
    }

    function renderSocialUpTab(): ReactNode {
      if (recentSocialUpAvisos.length === 0) {
        return (
          <div className="notices-popover-empty">
            <strong>Sem recados da SocialUp</strong>
            <span>Atualizações do produto e avisos gerais ficam reunidos aqui.</span>
          </div>
        );
      }

      if (recentSocialUpAvisos.length > 0) {
        return recentSocialUpAvisos.map((notice) => {
          const unread = !notice.readAt;
          const Icon = resolveAvisoPopoverIcon(notice);
          return (
            <article key={notice.id} className="notices-entry-card">
              <span className={`notices-entry-thumb ${resolveAvisoPopoverThumbClass(notice)}`} aria-hidden="true">
                <Icon />
              </span>
              <div className="notices-entry-copy">
                <div className="notices-entry-heading">
                  <strong>{notice.title}</strong>
                  <span className="notices-entry-time">{formatRelativeTime(notice.createdAt, effectiveUserTimeZone)}</span>
                </div>
                <span className="notices-entry-kicker">Equipe SocialUp</span>
                <p>{notice.message}</p>
              </div>
              <div className="notices-entry-side">
                {renderNoticeReadState({
                  unread,
                  busy: markingAvisoReadId === notice.id,
                  onMarkRead: () => void markAvisoAsRead(notice.id),
                  unreadLabel: "Marcar aviso como lido",
                  readLabel: "Aviso lido",
                })}
                <button
                  type="button"
                  className="notices-entry-delete"
                  aria-label="Excluir aviso"
                  title="Excluir aviso"
                  onClick={() => void deleteAvisoFromPopover(notice.id)}
                  disabled={deletingAvisoId === notice.id}
                >
                  <FiTrash2 aria-hidden="true" />
                </button>
              </div>
            </article>
          );
        });
      }
    }

    return (
      <div
        ref={shellRef}
        className={`notices-shell${noticesPopoverOpen ? " notices-shell-open" : ""}${extraClassName ? ` ${extraClassName}` : ""}`}
      >
        {noticesPopoverOpen ? (
          <div
            className="notices-backdrop"
            aria-hidden="true"
          />
        ) : null}
        <button
          type="button"
          className={`notices-trigger${noticesPopoverOpen ? " notices-trigger-active" : ""}`}
          onClick={() => void toggleNoticesPopover()}
          aria-label="Abrir avisos"
        >
          <FiBell />
          {hasUnreadNotices ? (
            <span className="notices-badge-dot" aria-hidden="true" />
          ) : null}
        </button>

        {noticesPopoverOpen ? (
          <section className="notices-popover" role="dialog" aria-label="Notificações">
            <div className="notices-popover-header">
              <div className="notices-popover-title-block">
                <strong>Notificações</strong>
              </div>
              <div className="notices-popover-meta">
                <button
                  type="button"
                  className="notices-panel-action"
                  onClick={openAvisosView}
                  title="Ver todas as notificações"
                  aria-label="Ver todas as notificações"
                >
                  <FiEye aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className="notices-panel-action"
                  onClick={() => void markAllAvisosAsRead()}
                  disabled={markingAllAvisosRead || noticesPopoverLoading || !canMarkAllNoticesAsRead}
                  title="Marcar todas como lidas"
                  aria-label="Marcar todas como lidas"
                >
                  {markingAllAvisosRead ? (
                    <span className="notices-double-check notices-double-check-loading">...</span>
                  ) : (
                    <span className="notices-double-check" aria-hidden="true">
                      <FiCheck />
                      <FiCheck />
                    </span>
                  )}
                </button>
              </div>
            </div>

            <div className="notices-panel-tabs" role="tablist" aria-label="Categorias de notificações">
              {tabs.map((tab) => (
                <button
                  key={tab.key}
                  type="button"
                  role="tab"
                  aria-selected={effectiveNoticesPopoverTab === tab.key}
                  className={`notices-panel-tab${effectiveNoticesPopoverTab === tab.key ? " notices-panel-tab-active" : ""}`}
                  onClick={() => setNoticesPopoverTab(tab.key)}
                >
                  <tab.icon aria-hidden="true" />
                  <span>{tab.label}</span>
                  <small className={`notices-panel-tab-count${tab.unreadCount > 0 ? " notices-panel-tab-count-active" : ""}`}>
                    {tab.unreadCount}
                  </small>
                </button>
              ))}
            </div>

            <div className="notices-popover-list">
              {effectiveNoticesPopoverTab === "panel"
                ? renderUpdatesTab()
                : effectiveNoticesPopoverTab === "feedbacks"
                  ? renderFeedbackTab()
                  : renderSocialUpTab()}
            </div>
          </section>
        ) : null}
      </div>
    );
  }

  function renderAuthScreen() {
    const showWorkspaceInvite = Boolean(workspaceInviteKey) && Boolean(workspaceInvitePreview);
    const showWorkspaceInviteCreate = showWorkspaceInvite && workspaceInviteMode === "create";
    const authLoginBusy = authSubmitting || googleAuthSubmitting || creatingSignupUser || requestingPasswordReset || confirmingPasswordReset;
    const showAuthModeTabs = !showWorkspaceInvite && (authMode === "login" || authMode === "signup");
    const showAuthSocialAccess = !showWorkspaceInvite && (authMode === "login" || authMode === "signup");

    return (
      <div className="auth-shell">
        <div className="auth-logo">
          <img src={activeAppLogo} alt="SocialUp" className="brand-logo auth-brand-logo" />
        </div>

        {showWorkspaceInviteCreate ? (
          <>
            <div className="auth-setup-copy">
              <h1>Entrar no workspace</h1>
              <p>
                {workspaceInvitePreview
                  ? `Você foi convidado para o workspace ${workspaceInvitePreview.workspace.name} como ${
                      workspaceInvitePreview.role === "CLIENT" ? "cliente" : "equipe da agência"
                    }.`
                  : "Crie sua conta para acessar o workspace compartilhado."}
              </p>
            </div>

            <section className="auth-panel-clean auth-panel-wide">
              {authError ? <div className="error-banner">{authError}</div> : null}
              {authInfo ? <div className={`info-banner${isPositiveAuthInfo ? " info-banner-success" : ""}`}>{authInfo}</div> : null}

              <form onSubmit={createUserFromWorkspaceInvite} className="form-stack">
                <input
                  value={setupName}
                  onChange={(event) => setSetupName(event.target.value)}
                  placeholder="Nome completo"
                  required
                  minLength={2}
                  maxLength={80}
                  title="Informe o nome completo do novo usuario."
                />
                <input
                  type="email"
                  value={setupEmail}
                  onChange={(event) => setSetupEmail(event.target.value)}
                  placeholder="Email"
                  required
                  maxLength={160}
                  title="Informe o email principal desta conta."
                />
                <input
                  value={setupUsername}
                  onChange={(event) => setSetupUsername(event.target.value)}
                  placeholder="Usuário"
                  required
                  minLength={3}
                  maxLength={32}
                  pattern="^[a-zA-Z0-9._-]+$"
                  title="Use apenas letras, numeros, ponto, traco ou underscore."
                />
                <input
                  type="password"
                  value={setupPassword}
                  onChange={(event) => setSetupPassword(event.target.value)}
                  placeholder="Senha"
                  required
                  minLength={8}
                  maxLength={128}
                  title="Defina uma senha com pelo menos 8 caracteres."
                />
                <button type="submit" disabled={creatingWorkspaceInviteUser}>
                  {creatingWorkspaceInviteUser ? "Criando..." : "Criar usuário"}
                </button>
                {showWorkspaceInviteCreate ? (
                  <button
                    type="button"
                    className="ghost-button"
                    onClick={() => setWorkspaceInviteMode("login")}
                    disabled={creatingWorkspaceInviteUser}
                  >
                    Já tenho conta
                  </button>
                ) : null}
              </form>
            </section>
          </>
        ) : (
          <>
            {showAuthModeTabs ? (
              <div className="auth-mode-tabs" role="tablist" aria-label="Acesso">
                <button
                  type="button"
                  role="tab"
                  aria-selected={authMode === "login"}
                  className={authMode === "login" ? "auth-mode-tab auth-mode-tab-active" : "auth-mode-tab"}
                  onClick={() => setAuthMode("login")}
                  disabled={authLoginBusy}
                >
                  Entrar
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={authMode === "signup"}
                  className={authMode === "signup" ? "auth-mode-tab auth-mode-tab-active" : "auth-mode-tab"}
                  onClick={() => setAuthMode("signup")}
                  disabled={authLoginBusy}
                >
                  Cadastrar
                </button>
              </div>
            ) : null}

            <section className="auth-panel-clean">
              {authError ? <div className="error-banner">{authError}</div> : null}
              {authInfo ? <div className={`info-banner${isPositiveAuthInfo ? " info-banner-success" : ""}`}>{authInfo}</div> : null}
              {showWorkspaceInvite && workspaceInvitePreview ? (
                <div className="field-hint" style={{ marginBottom: 16 }}>
                  {`Convite para ${workspaceInvitePreview.workspace.name} como ${
                    workspaceInvitePreview.role === "CLIENT" ? "cliente" : "equipe da agência"
                  }.`}
                </div>
              ) : null}

              {authMode === "forgot" && !showWorkspaceInvite ? (
                <form onSubmit={requestPasswordReset} className="form-stack">
                  <div className="auth-flow-copy">
                    <strong>Recuperar senha</strong>
                    <span>Informe seu email e enviaremos um link de recuperação.</span>
                  </div>
                  <input
                    type="email"
                    value={passwordResetEmail}
                    onChange={(event) => setPasswordResetEmail(event.target.value)}
                    placeholder="Email"
                    disabled={authLoginBusy}
                    required
                    maxLength={160}
                    title="Informe o email cadastrado."
                  />
                  <button type="submit" disabled={authLoginBusy}>
                    {requestingPasswordReset ? (
                      <>
                        <span className="button-spinner" aria-hidden="true" />
                        Enviando...
                      </>
                    ) : (
                      "Enviar link"
                    )}
                  </button>
                  <button
                    type="button"
                    className="ghost-button auth-secondary-action"
                    onClick={returnToLoginFromPasswordReset}
                    disabled={authLoginBusy}
                  >
                    Voltar para entrar
                  </button>
                </form>
              ) : authMode === "reset" && !showWorkspaceInvite ? (
                <form onSubmit={confirmPasswordReset} className="form-stack">
                  <div className="auth-flow-copy">
                    <strong>Criar nova senha</strong>
                    <span>Digite e confirme a nova senha para acessar o painel.</span>
                  </div>
                  <input
                    type="password"
                    value={passwordResetPassword}
                    onChange={(event) => setPasswordResetPassword(event.target.value)}
                    placeholder="Nova senha"
                    autoComplete="new-password"
                    disabled={authLoginBusy}
                    required
                    minLength={8}
                    maxLength={128}
                    title="Defina uma senha com pelo menos 8 caracteres."
                  />
                  <input
                    type="password"
                    value={passwordResetConfirmPassword}
                    onChange={(event) => setPasswordResetConfirmPassword(event.target.value)}
                    placeholder="Confirmar senha"
                    autoComplete="new-password"
                    disabled={authLoginBusy}
                    required
                    minLength={8}
                    maxLength={128}
                    title="Repita a nova senha."
                  />
                  <button type="submit" disabled={authLoginBusy}>
                    {confirmingPasswordReset ? (
                      <>
                        <span className="button-spinner" aria-hidden="true" />
                        Salvando...
                      </>
                    ) : (
                      "Salvar nova senha"
                    )}
                  </button>
                </form>
              ) : authMode === "signup" && !showWorkspaceInvite ? (
                <form onSubmit={createPublicUser} className="form-stack" autoComplete="off">
                  <input
                    value={setupName}
                    onChange={(event) => setSetupName(event.target.value)}
                    placeholder="Nome"
                    autoComplete="off"
                    disabled={authLoginBusy}
                    required
                    minLength={2}
                    maxLength={40}
                    title="Informe seu nome."
                  />
                  <input
                    value={setupLastName}
                    onChange={(event) => setSetupLastName(event.target.value)}
                    placeholder="Sobrenome"
                    autoComplete="off"
                    disabled={authLoginBusy}
                    required
                    minLength={2}
                    maxLength={60}
                    title="Informe seu sobrenome."
                  />
                  <input
                    type="email"
                    value={setupEmail}
                    onChange={(event) => setSetupEmail(event.target.value)}
                    placeholder="Email"
                    autoComplete="off"
                    disabled={authLoginBusy}
                    required
                    maxLength={160}
                    title="Informe seu email principal."
                  />
                  <input
                    type="password"
                    value={setupPassword}
                    onChange={(event) => setSetupPassword(event.target.value)}
                    placeholder="Senha"
                    autoComplete="new-password"
                    disabled={authLoginBusy}
                    required
                    minLength={8}
                    maxLength={128}
                    title="Defina uma senha com pelo menos 8 caracteres."
                  />
                  <button type="submit" disabled={authLoginBusy}>
                    {creatingSignupUser ? (
                      <>
                        <span className="button-spinner" aria-hidden="true" />
                        Cadastrando...
                      </>
                    ) : (
                      "Cadastrar"
                    )}
                  </button>
                </form>
              ) : (
                <form onSubmit={login} className="form-stack">
                  <input
                    value={loginIdentifier}
                    onChange={(event) => setLoginIdentifier(event.target.value)}
                    placeholder="Email ou usuário"
                    disabled={authLoginBusy}
                    required
                    minLength={3}
                    maxLength={160}
                    title="Informe seu email ou usuário."
                  />
                  <div className="password-field">
                    <input
                      type={showLoginPassword ? "text" : "password"}
                      value={loginPassword}
                      onChange={(event) => setLoginPassword(event.target.value)}
                      placeholder="Senha"
                      disabled={authLoginBusy}
                      required
                      minLength={8}
                      maxLength={128}
                      title="Informe sua senha."
                    />
                    <button
                      type="button"
                      className="password-toggle"
                      onClick={() => setShowLoginPassword((current) => !current)}
                      disabled={authLoginBusy}
                      aria-label={showLoginPassword ? "Ocultar senha" : "Mostrar senha"}
                    >
                      {showLoginPassword ? <FiEyeOff /> : <FiEye />}
                    </button>
                  </div>
                  <div className="auth-login-options-row">
                    <label className="auth-checkbox-row">
                      <input
                        type="checkbox"
                        checked={rememberMe}
                        onChange={(event) => setRememberMe(event.target.checked)}
                        disabled={authLoginBusy}
                      />
                      <span>Manter conectado</span>
                    </label>
                    <button
                      type="button"
                      className="auth-forgot-password-link"
                      disabled={authLoginBusy}
                      onClick={() => {
                        setPasswordResetEmail(loginIdentifier.includes("@") ? loginIdentifier : "");
                        setAuthMode("forgot");
                        setAuthError("");
                        setAuthInfo("");
                      }}
                    >
                      Esqueceu a senha?
                    </button>
                  </div>
                  <button type="submit" disabled={authLoginBusy}>
                    {authSubmitting ? (
                      <>
                        <span className="button-spinner" />
                        Entrando...
                      </>
                    ) : (
                      "Entrar"
                    )}
                  </button>
                  {showWorkspaceInvite ? (
                    <button
                      type="button"
                      className="ghost-button"
                      onClick={() => setWorkspaceInviteMode("create")}
                      disabled={authLoginBusy}
                    >
                      Primeiro acesso? Criar conta
                    </button>
                  ) : null}
                </form>
              )}
            </section>
            {showAuthSocialAccess ? <div className="auth-social-access">
              <div className="auth-provider-divider">
                <span>ou continue com</span>
              </div>
              <button
                type="button"
                className="ghost-button auth-social-button"
                onClick={() => void startGoogleLogin()}
                disabled={authLoginBusy}
              >
                {googleAuthSubmitting ? (
                  <>
                    <span className="button-spinner" aria-hidden="true" />
                    Entrando com Google...
                  </>
                ) : (
                  <>
                    <GoogleGlyph />
                    Entrar/Cadastrar com Google
                  </>
                )}
              </button>
            </div> : null}
          </>
        )}
      </div>
    );
  }

  function renderInitialPlanSelection() {
    const selectablePlans = initialTrialSelectablePlans;
    const trialPlanNetworks = ["instagram", "facebook", "threads", "x", "tiktok", "whatsapp"] as const;

    return (
      <div className="trial-onboarding-page">
        <div className="trial-onboarding-shell">
          <section className="trial-onboarding-head">
            <div className="trial-onboarding-hero-copy">
              <span className="section-kicker trial-onboarding-kicker">início rápido</span>
              <h1>
                <span>Escolha como quer </span>
                <span className="home-welcome-highlight">começar</span>
              </h1>
              <p>Defina o formato inicial da sua conta. Pagamento e catálogo a gente ajusta depois com calma.</p>
            </div>
          </section>

          {error ? <div className="error-banner">{error}</div> : null}
          {planInfo ? <div className={`info-banner${isPositivePlanInfo ? " info-banner-success" : ""}`}>{planInfo}</div> : null}

          {billingLoading ? (
            <section className="trial-onboarding-plan-grid" aria-hidden="true">
              {Array.from({ length: 2 }, (_, index) => (
                <article key={`trial-plan-skeleton-${index}`} className="panel-card trial-onboarding-plan-card trial-onboarding-plan-card-skeleton">
                  <div className="trial-onboarding-plan-head">
                    <div className="trial-onboarding-plan-title">
                      <span className="skeleton-line skeleton-line-chip" />
                      <span className="skeleton-line skeleton-line-title" />
                      <span className="skeleton-line skeleton-line-body" />
                    </div>
                  </div>
                  <div className="trial-onboarding-plan-features">
                    {Array.from({ length: 4 }, (_, itemIndex) => (
                      <span key={`trial-plan-skeleton-feature-${index}-${itemIndex}`} className="skeleton-line skeleton-line-text" />
                    ))}
                  </div>
                  <span className="skeleton-line skeleton-line-button" />
                </article>
              ))}
            </section>
          ) : selectablePlans.length === 0 ? (
            <section className="panel-card view-stack">
              <div className="empty-state">Nenhum plano inicial está disponível agora.</div>
            </section>
          ) : (
            <section className="trial-onboarding-plan-grid">
              {selectablePlans.map((plan) => {
                const normalizedCode = (plan.code || "").trim().toUpperCase();
                const isAgencyPlan = normalizedCode === "AGENCY";
                const featureBullets = plan.highlights.length > 0 ? plan.highlights : resolvePlanFeatureBullets(plan);
                const isStartingThisPlan = startingInitialTrialPlanId === plan.id;
                const selectedPriceCycle = resolvePlanCardBillingCycle(plan);

                return (
                  <article
                    key={plan.id}
                    className={`panel-card trial-onboarding-plan-card${isAgencyPlan ? " trial-onboarding-plan-card-featured" : ""}`}
                  >
                    <div className="trial-onboarding-plan-head">
                      <div className="trial-onboarding-plan-title">
                        <strong>{plan.name}</strong>
                        <p>{plan.subtitle || plan.description || "Plano inicial do seu workspace."}</p>
                        <div className="trial-onboarding-plan-platforms" aria-label="Redes disponíveis no sistema">
                          {trialPlanNetworks.map((network) => {
                            const Icon = socialPlatformIcon(network);
                            return (
                              <span
                                key={`${plan.id}-${network}`}
                                className={`trial-onboarding-plan-platform-icon trial-onboarding-plan-platform-icon-${network}`}
                                title={socialPlatformLabel(network)}
                                aria-label={socialPlatformLabel(network)}
                              >
                                <Icon aria-hidden="true" />
                              </span>
                            );
                          })}
                        </div>
                      </div>
                    </div>

                    <div className="trial-onboarding-plan-features">
                      {featureBullets.map((feature) => (
                        <span key={`${plan.id}-${feature}`} className="trial-onboarding-plan-feature-item">
                          <FiCheck aria-hidden="true" />
                          <span>{feature}</span>
                        </span>
                      ))}
                    </div>

                    <div className="trial-onboarding-plan-price">
                      {renderPlanBillingCycleToggle(plan, selectedPriceCycle)}
                      <strong>{resolvePlanCyclePriceLabel(plan, selectedPriceCycle)}</strong>
                    </div>

                    <button
                      type="button"
                      className="primary-button trial-onboarding-plan-button"
                      onClick={() => void startInitialTrial(plan)}
                      disabled={Boolean(startingInitialTrialPlanId)}
                    >
                      {isStartingThisPlan ? (
                        <>
                          <span className="button-spinner" aria-hidden="true" />
                          Continuando...
                        </>
                      ) : (
                        <>
                          Continuar com este plano
                          <FiChevronRight aria-hidden="true" />
                        </>
                      )}
                    </button>
                  </article>
                );
              })}
            </section>
          )}
        </div>
      </div>
    );
  }

  function renderDashboard() {
    const welcomeNameParts = authUser?.name?.trim().split(/\s+/).filter(Boolean) ?? [];
    const welcomeName = welcomeNameParts.slice(0, 2).join(" ") || "por aqui";
    const monthLabel = dashboardCalendarMonthLabel.charAt(0).toUpperCase() + dashboardCalendarMonthLabel.slice(1);
    const selectedDashboardPopoverJob = dashboardCalendarPopoverJobId
      ? dashboardCalendarJobs.find((job) => job.id === dashboardCalendarPopoverJobId) ?? null
      : null;
    const selectedDashboardPopoverGroupJobs = selectedDashboardPopoverJob
      ? schedulerGroupedJobsMap.get(resolveJobSchedulerGroupKey(selectedDashboardPopoverJob)) ?? [selectedDashboardPopoverJob]
      : [];
    const selectedDashboardPopoverLatestJobs = resolveLatestJobsPerCompanyPublicationType(selectedDashboardPopoverGroupJobs).sort(
      (left, right) => new Date(left.dataPostagem).getTime() - new Date(right.dataPostagem).getTime(),
    );
    const selectedDashboardPopoverParticipantNetworks = selectedDashboardPopoverJob
      ? resolveJobParticipantNetworks(selectedDashboardPopoverJob, selectedDashboardPopoverLatestJobs)
      : [];
    const selectedDashboardPopoverTitle = selectedDashboardPopoverJob
      ? resolveHistoryCalendarTitle(selectedDashboardPopoverJob)
      : "";
    const selectedDashboardPopoverWorkspaces = selectedDashboardPopoverJob
      ? Array.from(
          new Map(
            selectedDashboardPopoverGroupJobs.map((groupJob) => {
              const workspace = companyMapById[groupJob.companyId] ?? null;
              const workspaceColor = workspace?.color?.trim()
                ? workspace.color.trim()
                : DEFAULT_WORKSPACE_COLOR;
              return [
                groupJob.companyId,
                {
                  id: workspace?.id ?? groupJob.companyId,
                  label: workspace?.name?.trim() || companyNameMap[groupJob.companyId] || "Workspace removido",
                  color: workspaceColor,
                },
              ] as const;
            }),
          ).values(),
        )
      : [];
    const selectedDashboardPopoverMediaSourceJob =
      selectedDashboardPopoverGroupJobs.find((groupJob) => resolveJobMediaPaths(groupJob).length > 0) ??
      selectedDashboardPopoverJob;
    const selectedDashboardPopoverMediaPaths = selectedDashboardPopoverJob
      ? resolveJobMediaPaths(selectedDashboardPopoverMediaSourceJob ?? selectedDashboardPopoverJob)
      : [];
    const selectedDashboardPopoverHasMedia = selectedDashboardPopoverMediaPaths.length > 0;
    const selectedDashboardPopoverMediaCount = selectedDashboardPopoverMediaPaths.length;
    const selectedDashboardPopoverActiveMediaIndex = selectedDashboardPopoverMediaCount > 0
      ? Math.min(dashboardCalendarPopoverMediaIndex, selectedDashboardPopoverMediaCount - 1)
      : 0;
    const selectedDashboardPopoverActiveMediaPath = selectedDashboardPopoverMediaPaths[selectedDashboardPopoverActiveMediaIndex] ?? null;
    const selectedDashboardPopoverRunningLike = selectedDashboardPopoverGroupJobs.some((groupJob) =>
      shouldRenderUpcomingAsRunning(groupJob, isPastScheduledAtForUser),
    );
    const selectedDashboardPopoverFailedJobs = selectedDashboardPopoverLatestJobs.filter((groupJob) => groupJob.status === "FAILED");
    const selectedDashboardPopoverSuccessfulJobs = selectedDashboardPopoverLatestJobs.filter((groupJob) =>
      isSuccessfulPublicationJobStatus(groupJob.status),
    );
    const selectedDashboardPopoverSuccessfulNetworks = Array.from(
      new Set(selectedDashboardPopoverSuccessfulJobs.map((groupJob) => publicationTypeNetwork(groupJob.publicationType))),
    );
    const selectedDashboardPopoverRetryAnchorJobId = selectedDashboardPopoverFailedJobs[0]?.id ?? null;
    const selectedDashboardPopoverEditingTime = dashboardCalendarEditingJobId === selectedDashboardPopoverJob?.id;
    const selectedDashboardPopoverSavingTime = dashboardCalendarSavingJobId === selectedDashboardPopoverJob?.id;
    const selectedDashboardPopoverRetryingJob =
      selectedDashboardPopoverRetryAnchorJobId !== null && retryingJobId === selectedDashboardPopoverRetryAnchorJobId;
    const selectedDashboardPopoverReactivatingJob = togglingScheduleJobId === selectedDashboardPopoverJob?.id;
    const selectedDashboardPopoverCanManage =
      selectedDashboardPopoverJob ? canManagePublicationJob(selectedDashboardPopoverJob) : false;
    const selectedDashboardPopoverCanEditTime = selectedDashboardPopoverJob
      ? selectedDashboardPopoverCanManage &&
        canEditPublicationBoardSchedule(selectedDashboardPopoverJob) &&
        !isPastScheduledAtForUser(selectedDashboardPopoverJob.dataPostagem)
      : false;
    const selectedDashboardPopoverCanRetry = selectedDashboardPopoverCanManage && selectedDashboardPopoverFailedJobs.length > 0;
    const selectedDashboardPopoverCanReactivate = selectedDashboardPopoverJob
      ? selectedDashboardPopoverCanManage && canReactivatePublicationBoardJob(selectedDashboardPopoverJob)
      : false;
    const selectedDashboardPopoverStatusMeta = resolveGroupedPublicationStatusMeta(
      selectedDashboardPopoverLatestJobs,
      isPastScheduledAtForUser,
    );
    const selectedDashboardPopoverCanDuplicate =
      selectedDashboardPopoverCanManage && selectedDashboardPopoverFailedJobs.length === 0;

    return (
      <div className="view-stack">
        <section className="home-welcome-banner">
          <div className="home-welcome-copy">
            <small>Home</small>
            <h2>
              <span>Bem-vindo (a), </span>
              <span className="home-welcome-highlight">{welcomeName}</span>
            </h2>
          </div>
          {hasAnyPublicationManageWorkspace ? (
            <button
              type="button"
              className="primary-button publications-primary-action"
              onClick={() => navigateToView("scheduler")}
            >
              <FiFileText aria-hidden="true" />
              Nova publicação
            </button>
          ) : null}
        </section>

        <section className="panel-card home-calendar-shell">
          <div className="home-calendar-toolbar">
            <div className="home-calendar-toolbar-copy">
              <strong>
                <FiCalendar aria-hidden="true" />
                <span>Calendário do mês</span>
              </strong>
              <small>Veja seus agendamentos do mês e clique em um agendamento para abrir os detalhes.</small>
            </div>
            <div className="home-calendar-toolbar-actions">
              <span className="home-calendar-period-label">{monthLabel}</span>
              <button
                type="button"
                className="ghost-button home-calendar-nav-button"
                onClick={() => navigateDashboardCalendarMonth(-1)}
                aria-label="Mês anterior"
              >
                <FiChevronLeft />
              </button>
              <button
                type="button"
                className="ghost-button home-calendar-nav-button"
                onClick={() => navigateDashboardCalendarMonth(1)}
                aria-label="Próximo mês"
              >
                <FiChevronRight />
              </button>
            </div>
          </div>

          <div className="home-calendar-month">
            <div className="home-calendar-grid">
              {dashboardCalendarCells.map((cell) => (
                (() => {
                  const pageCount = Math.max(1, Math.ceil(cell.jobs.length / 4));
                  const currentPage = Math.min(dashboardCalendarDayPages[cell.dayKey] ?? 0, pageCount - 1);
                  const visibleJobs = cell.jobs.slice(currentPage * 4, currentPage * 4 + 4);

                  return (
                    <article
                      key={cell.key}
                      className={`home-calendar-day${cell.isToday ? " home-calendar-day-today" : ""}`}
                    >
                      <div className="home-calendar-day-head">
                        <strong>{cell.day}</strong>
                        <small>{cell.weekdayLabel}</small>
                      </div>

                      <div className="home-calendar-day-body">
                        {cell.jobs.length > 0
                          ? (
                              <div className="home-calendar-day-events-shell">
                                <div className="home-calendar-day-events">
                                  {visibleJobs.map((job) => {
                                    const dashboardJobTitleFull = resolveHistoryCalendarTitle(job);
                                    const dashboardJobTitle = clampCompactPublicationTitle(dashboardJobTitleFull, 11);
                                    const jobGroupItems = schedulerGroupedJobsMap.get(resolveJobSchedulerGroupKey(job)) ?? [job];
                                    const participantNetworks = resolveJobParticipantNetworks(job, jobGroupItems);
                                    const isRunningLike = jobGroupItems.some((groupJob) =>
                                      shouldRenderUpcomingAsRunning(groupJob, isPastScheduledAtForUser),
                                    );
                                    const isPopoverOpen = dashboardCalendarPopoverJobId === job.id;

                                    return (
                                      <div
                                        key={job.id}
                                        className={`home-calendar-entry-wrap${isPopoverOpen ? " home-calendar-entry-wrap-active" : ""}`}
                                      >
                                        <div
                                          className={`home-calendar-entry-row${
                                            isRunningLike ? " home-calendar-entry-row-running" : ""
                                          }`}
                                        >
                                          <button
                                            type="button"
                                            className={`home-calendar-entry${isPopoverOpen ? " home-calendar-entry-active" : ""}`}
                                            onClick={() => openDashboardCalendarPopover(job)}
                                            title={dashboardJobTitleFull}
                                            aria-label={dashboardJobTitleFull}
                                          >
                                            <span className="home-calendar-entry-copy">
                                              <span className="home-calendar-entry-title-row">
                                                <span className="home-calendar-entry-platforms" aria-label="Canais da publicação">
                                                  {participantNetworks.map((network) => {
                                                    const EntryPlatformIcon = socialPlatformIcon(network);
                                                    return (
                                                      <span
                                                        key={`${job.id}-entry-${network}`}
                                                        className={`home-calendar-entry-platform-item home-calendar-entry-platform-item-${network}`}
                                                        title={socialPlatformLabel(network)}
                                                        aria-label={socialPlatformLabel(network)}
                                                      >
                                                        <EntryPlatformIcon aria-hidden="true" />
                                                      </span>
                                                    );
                                                  })}
                                                </span>
                                                <span className="home-calendar-entry-title">{dashboardJobTitle}</span>
                                              </span>
                                              <span className="home-calendar-entry-time">
                                                <FiClock aria-hidden="true" />
                                                <span className="home-calendar-entry-time-label">
                                                  {toTimeLocal(job.dataPostagem, effectiveUserTimeZone) || "--:--"}
                                                </span>
                                              </span>
                                            </span>
                                          </button>
                                          {isRunningLike ? <span className="status-pill-spinner home-calendar-entry-spinner" aria-hidden="true" /> : null}
                                        </div>
                                      </div>
                                    );
                                  })}
                                </div>

                                {pageCount > 1 ? (
                                  <div className="home-calendar-day-pager">
                                    <span className="home-calendar-day-pager-count" aria-label={`Página ${currentPage + 1} de ${pageCount}`}>
                                      {currentPage + 1}/{pageCount}
                                    </span>
                                    <div className="home-calendar-day-pager-actions">
                                      <button
                                        type="button"
                                        className="ghost-button home-calendar-day-pager-button"
                                        onClick={() => setDashboardCalendarDayPage(cell.dayKey, currentPage - 1, cell.jobs.length)}
                                        disabled={currentPage === 0}
                                        aria-label="Itens anteriores do dia"
                                      >
                                        <FiChevronLeft />
                                      </button>
                                      <button
                                        type="button"
                                        className="ghost-button home-calendar-day-pager-button"
                                        onClick={() => setDashboardCalendarDayPage(cell.dayKey, currentPage + 1, cell.jobs.length)}
                                        disabled={currentPage >= pageCount - 1}
                                        aria-label="Próximos itens do dia"
                                      >
                                        <FiChevronRight />
                                      </button>
                                    </div>
                                  </div>
                                ) : null}
                              </div>
                            )
                          : <span className="home-calendar-day-empty" />}
                      </div>
                    </article>
                  );
                })()
              ))}
            </div>
          </div>
        </section>

        {selectedDashboardPopoverJob ? (
          <div
            className="home-calendar-popover-backdrop"
            onClick={() => closeDashboardCalendarPopover(selectedDashboardPopoverJob.id)}
          >
            <div className="home-calendar-popover-frame" onClick={(event) => event.stopPropagation()}>
              <button
                type="button"
                className="home-calendar-popover-close home-calendar-popover-close-floating"
                onClick={() => closeDashboardCalendarPopover(selectedDashboardPopoverJob.id)}
                aria-label="Fechar detalhes da publicação"
                title="Fechar"
              >
                <FiX aria-hidden="true" />
              </button>
              <div
                className="home-calendar-popover home-calendar-popover-modal"
                role="dialog"
                aria-modal="true"
                aria-label={`Detalhes da publicação ${selectedDashboardPopoverTitle}`}
              >
              <div className="home-calendar-popover-head">
                {selectedDashboardPopoverActiveMediaPath ? (
                  <div className="home-calendar-popover-title-media" aria-label="Prévia da mídia da publicação">
                    <div className="home-calendar-popover-title-media-stage">
                      {isVideoPath(selectedDashboardPopoverActiveMediaPath) ? (
                        <video
                          src={`${api.baseUrl}${selectedDashboardPopoverActiveMediaPath}`}
                          muted
                          playsInline
                          preload="metadata"
                        />
                      ) : (
                        <img
                          src={`${api.baseUrl}${selectedDashboardPopoverActiveMediaPath}`}
                          alt={`Prévia da mídia ${selectedDashboardPopoverActiveMediaIndex + 1}`}
                        />
                      )}
                    </div>
                    {selectedDashboardPopoverMediaCount > 1 ? (
                      <div className="home-calendar-popover-title-media-nav">
                        <button
                          type="button"
                          className="home-calendar-popover-media-nav-button"
                          onClick={() =>
                            setDashboardCalendarPopoverMediaIndex((current) =>
                              current <= 0 ? selectedDashboardPopoverMediaCount - 1 : current - 1
                            )
                          }
                          aria-label="Mídia anterior"
                        >
                          <FiChevronLeft aria-hidden="true" />
                        </button>
                        <span className="home-calendar-popover-media-counter">
                          {selectedDashboardPopoverActiveMediaIndex + 1}/{selectedDashboardPopoverMediaCount}
                        </span>
                        <button
                          type="button"
                          className="home-calendar-popover-media-nav-button"
                          onClick={() =>
                            setDashboardCalendarPopoverMediaIndex((current) =>
                              current >= selectedDashboardPopoverMediaCount - 1 ? 0 : current + 1
                            )
                          }
                          aria-label="Próxima mídia"
                        >
                          <FiChevronRight aria-hidden="true" />
                        </button>
                      </div>
                    ) : null}
                  </div>
                ) : null}
                <div
                  className={`home-calendar-popover-head-main${
                    selectedDashboardPopoverRunningLike ? " home-calendar-popover-head-main-running" : ""
                  }`}
                >
                  <div className="home-calendar-popover-title">
                    <strong>{selectedDashboardPopoverTitle}</strong>
                  </div>
                  <div className="home-calendar-popover-head-side">
                    <span
                      className={`publications-job-status-chip publications-job-status-chip-${selectedDashboardPopoverStatusMeta.tone} home-calendar-popover-status-chip${
                        selectedDashboardPopoverRunningLike ? " home-calendar-popover-status-chip-running" : ""
                      }`}
                    >
                      {selectedDashboardPopoverRunningLike ? (
                        <span className="home-calendar-popover-status-chip-content">
                          <span className="status-pill-spinner" aria-hidden="true" />
                          Executando
                        </span>
                      ) : (
                        selectedDashboardPopoverStatusMeta.label
                      )}
                    </span>
                  </div>
                </div>
              </div>

              <div className="home-calendar-popover-toolbar">
                <div className="home-calendar-popover-platforms" aria-label="Canais da publicação">
                  {selectedDashboardPopoverParticipantNetworks.map((network) => (
                    <span
                      key={`${selectedDashboardPopoverJob.id}-${network}`}
                      className="home-calendar-popover-platform-item"
                    >
                      {renderPublicationNetworkPill(network)}
                    </span>
                  ))}
                </div>
                <div className="home-calendar-popover-actions">
                  {selectedDashboardPopoverCanManage ? (
                    <>
                      {selectedDashboardPopoverCanDuplicate ? (
                        <button
                          type="button"
                          className="publications-board-action-button publications-board-action-button-duplicate"
                          title="Duplicar publicação"
                          aria-label="Duplicar publicação"
                          onClick={() => openPublicationDuplicateModal(selectedDashboardPopoverJob, { sourceJobs: selectedDashboardPopoverLatestJobs })}
                        >
                          <FiCopy aria-hidden="true" />
                        </button>
                      ) : null}
                      <button
                        type="button"
                        className="publications-board-action-button publications-board-action-button-delete"
                        title="Excluir publicação"
                        aria-label="Excluir publicação"
                        onClick={() => void deleteGroupedHistoryJobs(selectedDashboardPopoverLatestJobs)}
                      >
                        <FiTrash2 aria-hidden="true" />
                      </button>
                    </>
                  ) : null}
                  {selectedDashboardPopoverCanRetry ? (
                    <button
                      type="button"
                      className="publications-board-action-button publications-board-action-button-retry"
                      title="Tentar novamente"
                      aria-label="Tentar novamente"
                      onClick={() => void retryGroupedJobs(selectedDashboardPopoverFailedJobs, selectedDashboardPopoverRetryAnchorJobId!)}
                      disabled={selectedDashboardPopoverRetryingJob}
                    >
                      <FiRotateCcw aria-hidden="true" />
                    </button>
                  ) : null}
                  {selectedDashboardPopoverCanReactivate ? (
                    <button
                      type="button"
                      className="publications-board-action-button publications-board-action-button-reactivate"
                      title="Reativar publicação"
                      aria-label="Reativar publicação"
                      onClick={() => void toggleJobSchedule(selectedDashboardPopoverJob)}
                      disabled={selectedDashboardPopoverReactivatingJob}
                    >
                      <FiCheckCircle aria-hidden="true" />
                    </button>
                  ) : null}
                </div>
              </div>

              <div className="home-calendar-popover-body">
                {selectedDashboardPopoverFailedJobs.length > 0 ? (
                  <div className="home-calendar-popover-summary-block">
                    <strong>Falhas</strong>
                    <div className="home-calendar-popover-failed-list">
                      {selectedDashboardPopoverFailedJobs.map((job) => (
                        <article key={`home-failed-${job.id}`} className="home-calendar-popover-failed-card">
                          <div className="home-calendar-popover-failed-card-main">
                            {renderPublicationTypePill(job.publicationType)}
                            <small>
                              {clampPublicationPreviewTargetLabel(
                                job.loginIdentifier?.trim() || companyNameMap[job.companyId] || "Conta conectada",
                                15,
                              )}
                            </small>
                          </div>
                          <span className="publications-job-status-chip publications-job-status-chip-failed">Falhou</span>
                        </article>
                      ))}
                    </div>
                  </div>
                ) : null}
                <div className="home-calendar-popover-detail-grid">
                  <span className="home-calendar-popover-detail-card">
                    <strong>Agendada para</strong>
                    <small>{formatJobScheduledAt(selectedDashboardPopoverJob, effectiveUserTimeZone)}</small>
                  </span>
                  <span className="home-calendar-popover-detail-card">
                    <strong>Workspace(s)</strong>
                    <small className="home-calendar-popover-workspaces">
                      {selectedDashboardPopoverWorkspaces.map((workspace, index) => (
                        <span key={workspace.id} className="home-calendar-popover-workspace-entry">
                          <span
                            className="home-calendar-popover-workspace-value"
                            style={{ color: workspace.color || DEFAULT_WORKSPACE_COLOR }}
                          >
                            {workspace.label}
                          </span>
                          {index < selectedDashboardPopoverWorkspaces.length - 1 ? (
                            <span className="home-calendar-popover-workspace-separator" aria-hidden="true">
                              ,{" "}
                            </span>
                          ) : null}
                        </span>
                      ))}
                    </small>
                  </span>
                </div>
              </div>

              {selectedDashboardPopoverCanEditTime && selectedDashboardPopoverEditingTime ? (
                <div className="home-calendar-popover-time-editor publications-board-inline-schedule-editor">
                  <input
                    type="time"
                    value={dashboardCalendarTimeValue}
                    onChange={(event) => setDashboardCalendarTimeValue(event.target.value)}
                    disabled={selectedDashboardPopoverSavingTime}
                  />
                  <div className="publications-board-inline-schedule-actions">
                    <button
                      type="button"
                      className="publications-board-inline-schedule-save"
                      title="Salvar horário"
                      aria-label="Salvar horário"
                      onClick={() => void saveDashboardCalendarTime(selectedDashboardPopoverJob)}
                      disabled={selectedDashboardPopoverSavingTime}
                    >
                      <FiCheckCircle aria-hidden="true" />
                    </button>
                    <button
                      type="button"
                      className="publications-board-inline-schedule-cancel"
                      title="Cancelar edição de horário"
                      aria-label="Cancelar edição de horário"
                      onClick={() => {
                        setDashboardCalendarEditingJobId(null);
                        setDashboardCalendarTimeValue("");
                      }}
                      disabled={selectedDashboardPopoverSavingTime}
                    >
                      <FiX aria-hidden="true" />
                    </button>
                  </div>
                </div>
              ) : null}
              </div>
            </div>
          </div>
        ) : null}
      </div>
    );
  }

  function renderCompanyFilter(label: string) {
    return (
      <div className="inline-filter">
        <span>{label}</span>
        <select value={selectedCompanyId} onChange={(event) => setSelectedCompanyId(event.target.value)}>
          <option value="">Todas</option>
          {companies.map((company) => (
            <option key={company.id} value={company.id}>
              {company.name}
            </option>
          ))}
        </select>
      </div>
    );
  }

